# ===================================================================== 24
add(id=24, title="Mathematical foundations for evidence synthesis", last_verified=V, prerequisites=["None (school algebra)"],
 objectives=["Use logarithms and exponentials to move between ratio and difference scales.", "Compute and interpret weighted means and sums of squares.", "Propagate variances through sums, differences and simple transformations (the delta method idea)."],
 why="Almost every effect size in a meta-analysis lives on a log or transformed scale, and every pooled estimate is a weighted mean. A reader who is comfortable with logs, weights and variance arithmetic can check any calculation by hand and notice when software output is implausible.",
 plain="""**Logarithms turn ratios into differences.** A risk ratio of 2 means 'twice as likely'; a risk ratio of 0.5 means 'half as likely'. On the ratio scale these are not symmetric about 1, but on the log scale they are: ln 2 = 0.693 and ln 0.5 = −0.693. That is why ratio measures (OR, RR, HR, response ratio) are meta-analysed on the **log scale** and only back-transformed with exp() for reporting: exp(0.693) = 2.

**A weighted mean** gives more influence to more reliable numbers: Σ wᵢyᵢ / Σ wᵢ. In meta-analysis the weights are usually **inverse variances** wᵢ = 1/vᵢ, because a study with a small variance carries more information.

**Variance arithmetic.** For independent quantities, Var(a + b) = Var(a) + Var(b) and also Var(a − b) = Var(a) + Var(b) - variances always add. Multiplying a quantity by a constant c multiplies its variance by c². These three rules explain most formulas for standard errors of differences, changes and contrasts.""",
 intermediate="""**The delta method** approximates the variance of a smooth transformation g(X): Var(g(X)) ≈ g′(μ)² Var(X). Examples you will meet: Var(ln X) ≈ Var(X)/μ² (why the variance of a log risk ratio involves 1/events), and Var(tanh⁻¹ r) ≈ 1/(n − 3) (Fisher's z). The approximation is good for large samples and poor for small counts, which is why zero-cell and rare-event methods exist (Module 48).

**Sums of squares and 'degrees of freedom'.** The sample variance divides Σ(x − x̄)² by n − 1, not n, because x̄ was estimated from the same data (one 'degree of freedom' is used). Cochran's Q is a weighted sum of squares around the pooled mean and has k − 1 degrees of freedom for the same reason.

**Matrices (preview).** Multilevel and network models (Modules 39, 42) write the same ideas with vectors: estimate = (XᵀWX)⁻¹XᵀWy. You do not need matrix algebra to read the first 40 modules; it is introduced when it first becomes useful.""",
 advanced="""Numerical stability matters: inverse variances can differ by orders of magnitude, so software works with scaled quantities and solves linear systems rather than inverting matrices. Be careful with the log of a quantity that can be zero (a zero cell makes the log odds ratio undefined; continuity corrections are a pragmatic patch that changes the estimate - see Module 48). Know the limits of the delta method: it fails when the denominator can be close to zero (ratio of means with a mean near 0).""",
 assumptions=["Quantities combined by simple variance addition are independent (otherwise covariances enter).", "Delta-method variances assume a smooth transformation and a reasonably large sample."],
 formulas=[dict(name="Weighted mean with inverse-variance weights", tex=r"\bar y_w=\frac{\sum w_i y_i}{\sum w_i},\qquad w_i=\frac1{v_i},\qquad \mathrm{Var}(\bar y_w)=\frac1{\sum w_i}", symbols={"y_i":"study estimates","v_i":"their variances","w_i":"weights"}),
           dict(name="Variance rules (independent a, b; constant c)", tex=r"\mathrm{Var}(a\pm b)=\mathrm{Var}(a)+\mathrm{Var}(b),\qquad \mathrm{Var}(c\,a)=c^2\mathrm{Var}(a)", symbols={"a,b":"independent estimates","c":"constant"})],
 worked_example="""(1) **Ratio to log scale:** ln 2 = **0.6931** and ln 0.5 = **−0.6931**; exp(0.6931) = **2.0000**. (2) **Weighted mean:** estimates 0.2, 0.5, 0.8 with variances 0.04, 0.04, 0.16 → weights 25, 25, 6.25; weighted mean = (5 + 12.5 + 5)/56.25 = **0.40**, variance 1/56.25 = **0.0178** (SE 0.1333) - the same numbers used in Lesson 32. (3) **Variance of a difference:** two independent group means with SEs 0.3 and 0.4 have a difference with SE √(0.09 + 0.16) = **0.5**, not 0.7.""",
 examples=[("Preclinical","Log response ratio of lifespan: ln(48/40) = 0.182."),("Clinical","Odds ratios averaged on the log scale."),("Ecology","Back-transforming a mean log response ratio to a percentage change."),("Genetics","Combining independent effect estimates by inverse variance."),("Education","SE of a pre-post difference.")],
 mistakes=["Averaging risk ratios on the raw scale (the average of 0.5 and 2 is 1.25, but the typical effect is no effect: 1.0).","Subtracting variances for a difference.","Dividing by n instead of n − 1 for a sample variance.","Confusing SD with variance when combining."],
 misconceptions=[("'A risk ratio of 0.5 and 2 cancel out on the raw scale.'","Only on the log scale: ln 0.5 + ln 2 = 0."),("'The SE of a difference is the difference of SEs.'","Variances add: √(SE₁² + SE₂²).")],
 controversies=["How much mathematics a practising biologist needs before running meta-analyses (a pragmatic position: enough to check every number by hand once).", "Continuity corrections for zeros (Module 48)."],
 decision_tree=[("Ratio measure?","Work on the log scale; back-transform at the end."),("Combining independent estimates?","Add variances."),("Averaging estimates of different precision?","Inverse-variance weights."),("Variance of a transformation?","Delta method, if the sample is large enough.")],
 exercises=["Compute ln(3), ln(1/3) and exp of each by hand/calculator.", "Pool 0.1 (v 0.05) and 0.5 (v 0.02) by inverse variance and compute the variance of the pooled estimate.", "A mean has SD 4 and n = 16; find the SE, then the SE of a difference between two such independent means."],
 integrity="Back-transform only at the reporting stage and say which scale a number is on; never present a log-scale CI as if it were on the raw scale.", further=["borenstein2009book","viechtbauer2010","altman2005"],
 coding=dict(r='log(2); exp(log(2)); log(0.5)\ny <- c(0.2, 0.5, 0.8); v <- c(0.04, 0.04, 0.16); w <- 1 / v\nc(sum(w * y) / sum(w), 1 / sum(w), sqrt(1 / sum(w)))   # 0.40 0.0178 0.1333\nsqrt(0.3^2 + 0.4^2)                                      # 0.5', python='import math\ny=[0.2,0.5,0.8]; v=[0.04,0.04,0.16]; w=[1/x for x in v]\nprint(math.log(2), sum(a*b for a,b in zip(w,y))/sum(w), 1/sum(w), math.sqrt(0.3**2+0.4**2))'),
 application="**Milestone 3/7:** before using a calculator, redo one effect size by hand; record the scale (raw/log) of each effect in the extraction form.", checklist=["Scale of every effect recorded","Ratio measures on log scale","Variances (not SDs) combined","One calculation checked by hand"],
 quiz=[dict(q="ln(0.5) is closest to:", opts=["−0.693","0.693","−0.5","0.5"], ans=0, why="ln(0.5) = −ln(2) = −0.6931.", numeric=True),
  dict(q="Two independent means have SEs 0.3 and 0.4. The SE of their difference is:", opts=["0.5","0.7","0.1","0.25"], ans=0, why="√(0.3²+0.4²) = 0.5.", numeric=True),
  dict(q="Why are ratio effect sizes pooled on the log scale?", opts=["Ratios of 2 and 0.5 are symmetric about 0 on the log scale and the log-ratio is approximately normal","Logs are easier to type","Software requires it","Ratios cannot be averaged"], ans=0, why="Symmetry and approximate normality."),
  dict(q="Inverse-variance weights give...", opts=["More weight to studies with smaller variances","More weight to larger effects","Equal weights","More weight to older studies"], ans=0, why="w = 1/v."),
  dict(q="The pooled variance of weights 25, 25, 6.25 is:", opts=["0.0178","0.04","56.25","0.133"], ans=0, why="1/56.25 = 0.01778.", numeric=True)])

# ===================================================================== 25
add(id=25, title="Descriptive and inferential statistics for reviewers", last_verified=V, prerequisites=["Module 24"],
 objectives=["Distinguish SD (spread of observations) from SE (precision of a mean).", "Construct and interpret confidence intervals with the t distribution.", "Read a p-value, a CI and a test of heterogeneity without common misinterpretations."],
 why="Meta-analysis inputs are descriptive statistics (means, SDs, SEs, CIs, p-values) reported in the primary papers. Reviewers who confuse SD with SE or misread a CI will mis-extract data and mis-interpret pooled results.",
 plain="""The **standard deviation (SD)** describes how spread out individual observations are; it does not shrink as you collect more data. The **standard error (SE = SD/√n)** describes how precisely a *mean* is estimated; it shrinks with √n (Altman & Bland 2005 give the classic short explanation). A **95% confidence interval** is a procedure that captures the true value in about 95% of repeated experiments; for a mean from n observations it is x̄ ± t(0.975, n − 1) × SE. The t multiplier is larger than 1.96 for small n (2.262 for n = 10).

A **p-value** is the probability of results at least this extreme **if the null hypothesis and all other model assumptions were true**. It is not the probability that the null is true, not the size of an effect, and not a measure of importance. A non-significant result is *absence of evidence*, not evidence of absence - unless the CI is narrow around no effect.""",
 intermediate="""**Reported-value traps** (Module 18): '± ' may mean SD or SE; error bars may be SD, SE or CI; n may count animals or independent units (Module 85). **Skew:** means and SDs describe symmetric data; for skewed lifespans or concentrations medians/IQRs may be reported and need conversion methods (Wan et al. 2014) with warnings. **Multiple testing:** if many outcomes are tested, some will be 'significant' by chance; pre-specify primary outcomes. **Equivalence of tests and CIs:** a 95% CI that excludes 0 corresponds to p < 0.05, but the CI also shows magnitude and precision - report both.""",
 advanced="""Frequentist inference is defined by long-run behaviour of procedures; Bayesian inference answers 'what do we believe given the data and a prior' (Module 41). The two coincide approximately with large samples and vague priors. Power and 'post-hoc power' (computed from the observed effect) add nothing beyond the p-value and should not be reported. Statistical significance in individual studies should never be used to weight or select studies in a synthesis.""",
 assumptions=["Observations are independent (within the unit used for n).", "The sampling distribution of the mean is approximately normal (large n, or approximately normal data).", "SDs are the SDs of individual observations, not of means."],
 formulas=[dict(name="Standard error and CI for a mean", tex=r"SE=\frac{s}{\sqrt n},\qquad \bar x\;\pm\;t_{0.975,\,n-1}\,SE", symbols={"s":"sample SD","n":"sample size","t":"t quantile with n-1 df"})],
 worked_example="""n = 10 observations with SD = 2: SE = 2/√10 = **0.6325**; t(0.975, 9) = **2.2622**, so the CI half-width is 2.2622 × 0.6325 = **1.4307** (using 1.96 would give 1.24 - too narrow). If the same SD came from n = 40, SE = 0.316: four times the data halves the SE.""",
 examples=[("Preclinical","SD of lifespan within a vial-mean vs SD of vial means."),("Clinical","Trial arm means with 95% CIs."),("Ecology","Skewed biomass data reported as medians."),("Genetics","Expression fold changes with technical replicates."),("Education","Test-score SDs by class.")],
 mistakes=["Treating an SE as an SD (or vice versa).","Interpreting p > 0.05 as 'no effect'.","Using z = 1.96 for small samples.","Reporting post-hoc power."],
 misconceptions=[("'A 95% CI contains the true value with 95% probability.'","The procedure captures the true value in 95% of repeated experiments; a given interval either does or does not."),("'Smaller p means bigger effect.'","p depends on effect and precision.")],
 controversies=["Dichotomising results at p = 0.05.", "Confidence vs credible intervals.", "Whether to report p-values at all in a meta-analysis (report estimates and intervals; p secondary)."],
 decision_tree=[("Is '±' SD or SE?","Check the legend/methods; if unclear record 'unclear' and run a sensitivity analysis (Module 18)."),("Skewed data and medians?","Use conversion methods only with a labelled sensitivity analysis (Wan et al. 2014)."),("Small n?","Use t quantiles."),("Only a p-value given?","Back-calculate SE with caution (Module 18).")],
 exercises=["Compute SE and 95% CI for n = 8, mean 5.2, SD 1.4.", "Show how the CI changes if you wrongly use z = 1.96.", "Explain in two sentences why SD does not shrink with n but SE does."],
 integrity="Do not interpret non-significance as absence of effect, and report the CI with every estimate.", further=["altman2005","wan2014","borenstein2009book"],
 coding=dict(r='n <- 10; s <- 2\nse <- s / sqrt(n); c(se, qt(0.975, n - 1), qt(0.975, n - 1) * se)   # 0.6325 2.2622 1.4307', python='import math\nfrom scipy import stats\nn,s=10,2; se=s/math.sqrt(n); t=stats.t.ppf(0.975,n-1); print(se,t,t*se)'),
 application="**Milestone 7:** for each study, record whether ± is SD or SE and the unit behind n.", checklist=["SD/SE status recorded","n = independent units","CIs use t for small n","No 'no effect' claims from p > 0.05"],
 quiz=[dict(q="n = 10, SD = 2. SE =", opts=["0.632","2","0.2","6.32"], ans=0, why="2/√10.", numeric=True),
  dict(q="95% CI half-width for that sample (t-based)?", opts=["1.43","1.24","0.63","2.26"], ans=0, why="2.2622 × 0.6325.", numeric=True),
  dict(q="SD changes with n? ", opts=["No - it estimates the population spread","Yes, it shrinks","Yes, it grows","Only for medians"], ans=0, why="SE shrinks, SD does not."),
  dict(q="p = 0.20 means...", opts=["Data are fairly compatible with the null under the model; it does not show no effect","The null is 20% likely","The effect is small","The effect is zero"], ans=0, why="Standard interpretation."),
  dict(q="Why avoid post-hoc power?", opts=["It is a one-to-one function of p and adds no information","It is too complicated","It needs R","It is always 80%"], ans=0, why="Observed ('post-hoc') power is a function of the p-value.")])

# ===================================================================== 26
add(id=26, title="Statistical estimation and uncertainty", last_verified=V, prerequisites=["Modules 24, 25"],
 objectives=["Explain likelihood, maximum likelihood (ML) and restricted maximum likelihood (REML) in words and numbers.", "Understand why variance estimators are biased and how REML reduces the bias.", "Distinguish uncertainty about an estimate from heterogeneity in the world."],
 why="Choosing τ² estimators (DL, REML, PM) is a methodological decision with consequences for every random-effects analysis. Knowing what an estimator tries to do lets you justify a pre-specified choice and read sensitivity analyses sensibly.",
 plain="""An **estimator** is a recipe that turns data into an estimate. We judge estimators by **bias** (does it aim at the right value on average?), **variance** (how much does it fluctuate?) and **robustness** (does it behave when assumptions are violated?). The **likelihood** is the probability of the observed data viewed as a function of the unknown parameters; **maximum likelihood** picks the parameter values that make the observed data most probable.

ML variance estimates are biased downwards because they treat the estimated mean as if it were known. For the numbers 2, 4, 9: mean 5, sum of squares 26; ML variance = 26/3 = **8.67**; the unbiased estimator 26/2 = **13**. **REML** removes the nuisance mean from the likelihood before estimating variance components and gives the 26/2 answer in this simple case. In meta-regression and multilevel models REML is preferred for variance components for the same reason.""",
 intermediate="""**Estimating τ²** (the between-study variance) has no single best method: DerSimonian-Laird is simple but biased with few/small studies; REML and Paule-Mandel are common recommended defaults; Veroniki et al. (2016) and Langan et al. (2019) review the evidence and recommend pre-specifying the estimator and showing a sensitivity check. Viechtbauer (2005) compares bias and efficiency of the classical estimators. **Uncertainty of τ² itself is large**: with 10 studies the CI for τ² is usually very wide (Module 35); report it (Q-profile).

**Heterogeneity is not uncertainty.** If the true effects genuinely differ across studies (heterogeneity), more studies do not remove it; they just estimate it better. Uncertainty about the *mean* effect shrinks with more studies; the *spread of true effects* (τ) does not.""",
 advanced="""REML maximises the likelihood of linear combinations of the data free of the fixed effects; REML likelihoods can be compared only between models with the same fixed effects (use ML for fixed-effect comparisons). Estimates on a boundary (τ² = 0) give flat likelihoods; reporting 'no heterogeneity' there is wrong - the data are simply compatible with a range of small values. Profile likelihood and Bayesian intervals respect the constraint τ² ≥ 0 better than Wald intervals.""",
 assumptions=["Observations within the model are independent given the model (or the dependence is modelled).", "The assumed distribution (normal sampling errors, normal random effects) is adequate.", "Within-study variances are treated as known."],
 formulas=[dict(name="ML versus unbiased variance", tex=r"\hat\sigma^2_{ML}=\frac1n\sum(x_i-\bar x)^2,\qquad s^2=\frac1{n-1}\sum(x_i-\bar x)^2", symbols={"n":"sample size"})],
 worked_example="""Data 2, 4, 9: mean = **5**, Σ(x − x̄)² = **26**. ML variance = 26/3 = **8.667**; unbiased (and REML) = 26/2 = **13**. The ML estimator is too small by the factor (n − 1)/n = 2/3 on average. With n = 30 the factor is 0.967: the bias fades with larger n but is material for the small k typical in meta-analysis.""",
 examples=[("Preclinical","τ² across a dozen lifespan studies."),("Clinical","Few-trial meta-analyses."),("Ecology","Many effects, few studies."),("Genetics","Variance components for strain differences."),("Education","Effect heterogeneity across schools.")],
 mistakes=["Using DL by default without justification.","Reading τ² = 0 as 'homogeneous'.","Comparing REML fits of models with different fixed effects.","Selecting the estimator after seeing the results."],
 misconceptions=[("'More studies make heterogeneity disappear.'","They estimate it better, they do not remove it."),("'REML is always best.'","It is a reasonable pre-specified default, not a universal optimum (Langan et al. 2019).")],
 controversies=["Default τ² estimator.", "Wald vs profile-likelihood vs Bayesian intervals.", "Truncating negative estimates at zero."],
 decision_tree=[("Few studies (<5)?","Prefer a Bayesian approach with a justified prior or report with strong caveats (Module 41)."),("Choosing τ² estimator?","Pre-specify (REML or PM) and report a sensitivity analysis."),("Comparing models?","Use ML for fixed effects; REML for variance structure.")],
 exercises=["Compute ML and unbiased variance for 1, 3, 8.", "Pool a small dataset in the Statistics Lab with DL, REML and PM and note the range of τ².", "Explain to a colleague why τ² = 0 is not evidence of homogeneity."],
 integrity="Pre-specify the τ² estimator and report the sensitivity analysis; do not switch estimators to obtain a preferred result.", further=["viechtbauer2005","veroniki2016","langan2019"],
 coding=dict(r='x <- c(2, 4, 9)\nc(mean(x), sum((x - mean(x))^2), mean((x - mean(x))^2), var(x))   # 5 26 8.667 13', python='import numpy as np\nx=np.array([2,4,9.]); print(x.mean(), ((x-x.mean())**2).sum(), x.var(ddof=0), x.var(ddof=1))'),
 application="**Milestone 8:** write the pre-specified τ² estimator and sensitivity estimator into the statistical analysis plan.", checklist=["τ² estimator pre-specified","Sensitivity estimator named","τ² CI reported","Boundary estimates flagged"],
 quiz=[dict(q="ML variance of 2, 4, 9 is:", opts=["8.67","13","26","5"], ans=0, why="26/3.", numeric=True),
  dict(q="Unbiased variance of 2, 4, 9:", opts=["13","8.67","5","26"], ans=0, why="26/2.", numeric=True),
  dict(q="REML differs from ML mainly because it...", opts=["Accounts for estimating the fixed effects, reducing variance bias","Ignores the data","Is Bayesian","Always gives zero"], ans=0, why="Restricted likelihood."),
  dict(q="τ² = 0 means...", opts=["The estimate hit the boundary; data are compatible with small heterogeneity","No heterogeneity exists","Perfect studies","Fixed effect is correct"], ans=0, why="Boundary solutions are uninformative."),
  dict(q="More studies mainly reduce...", opts=["Uncertainty about the mean effect (not the true spread τ)","True heterogeneity","Bias in every study","The need for RoB"], ans=0, why="Estimation precision vs true variability.")])

# ===================================================================== 29
add(id=29, title="Correlation and regression effects", last_verified=V, prerequisites=["Modules 24, 25, 27"],
 objectives=["Choose among correlation, standardised mean difference and regression slope as the effect measure.", "Meta-analyse correlations with Fisher's z and back-transform correctly.", "Convert between r and d with explicit assumptions."],
 why="Many biological and social-science questions are about association (dose-trait, expression-phenotype), not group differences. The wrong scale or an incorrect conversion produces apparent heterogeneity or biased pooled estimates.",
 plain="""The **Pearson correlation r** (−1 to 1) summarises linear association. Its sampling distribution is skewed (especially near ±1) and its variance depends on r itself, so meta-analysts transform with **Fisher's z = atanh(r)** = ½ ln((1 + r)/(1 − r)). On the z scale the variance is approximately **1/(n − 3)**, which depends only on the sample size. Pool z values with inverse-variance weights and back-transform the pooled z and its CI with **r = tanh(z)**.

A regression **slope** has units (e.g. days per °C). Slopes from different studies are comparable only if the predictor and outcome are measured on the same scales; otherwise use standardised slopes or correlations and say so.""",
 intermediate="""**r and d.** For two equal groups, d = 2r/√(1 − r²) and r = d/√(d² + 4) (point-biserial). With unequal groups the conversion includes a correction term; when you convert you also change the variance formula. **Partial correlations and adjusted slopes** from models with different covariates are not on a common scale: record the covariate set and do not pool without thinking. **Range restriction** (studying only extreme groups) attenuates or inflates r; **measurement error** attenuates r (psychometric corrections exist but are model-dependent). **Dependence:** several correlations from the same sample need a multilevel or robust model (Modules 39-40).""",
 advanced="""Fisher's z pooling targets the mean z, which back-transforms to a non-linear function; interpret 'pooled r' as tanh(mean z), not the mean of r. Hunter-Schmidt methods pool raw r with artefact corrections and have different properties; compare approaches when reproducing older literature. For meta-regression of slopes use the SE of the slope; for standardised betas beware that they are sample-SD dependent.""",
 assumptions=["Bivariate normality is approximate (z-transform variance formula).", "n counts independent observations.", "Correlations pooled address the same two constructs measured similarly."],
 formulas=[dict(name="Fisher z and variance", tex=r"z=\operatorname{atanh}(r)=\tfrac12\ln\frac{1+r}{1-r},\qquad \mathrm{Var}(z)=\frac1{n-3},\qquad r=\tanh(z)", symbols={"r":"correlation","n":"sample size"}),
           dict(name="r to d (equal groups)", tex=r"d=\frac{2r}{\sqrt{1-r^2}}", symbols={"r":"point-biserial correlation"})],
 worked_example="""r = 0.50, n = 28. z = atanh(0.5) = **0.5493**; Var(z) = 1/25 = **0.0400**, SE = 0.2. 95% CI on z: 0.5493 ± 1.96×0.2 = 0.1573 to 0.9413. Back-transformed: r CI = tanh(0.157) to tanh(0.941) = **0.156 to 0.736** - asymmetric about 0.50, as it should be. Converted to d (equal groups): 2(0.5)/√(1 − 0.25) = **1.1547**.""",
 examples=[("Preclinical","Correlation between biomarker and lifespan across strains."),("Clinical","Dose-response slopes."),("Ecology","Body size-fecundity correlations."),("Genetics","Heritability-like associations."),("Education","Study time-score correlation.")],
 mistakes=["Averaging r directly when n varies widely.","Using n instead of n − 3 in the z variance.","Converting r to d without stating the group-size assumption.","Pooling adjusted slopes with different covariates."],
 misconceptions=[("'The pooled r is the mean of the r values.'","Pool z and back-transform."),("'r and d are interchangeable.'","Different scales; conversion assumptions apply.")],
 controversies=["Fisher z vs Hunter-Schmidt approaches.", "Corrections for measurement error and range restriction."],
 decision_tree=[("Association between two continuous variables?","Correlation (z) or slope per pre-specified rule."),("Same units?","Slope can be pooled."),("Different units?","Standardised effect (r or standardised slope)."),("Multiple correlations per sample?","Multilevel/RVE (Modules 39-40).")],
 exercises=["Convert r = 0.30, n = 50 to z, SE and a 95% CI for r.", "Convert d = 0.8 (equal groups) to r.", "List what you need from a paper reporting an adjusted regression slope before you can pool it."],
 integrity="State the effect-size scale and every conversion in the extraction form; do not mix adjusted and unadjusted estimates silently.", further=["borenstein2009book","nakagawa2012","viechtbauer2010"],
 coding=dict(r='r <- 0.5; n <- 28\nz <- atanh(r); se <- sqrt(1 / (n - 3))\nc(z, se, tanh(z - 1.96 * se), tanh(z + 1.96 * se), 2 * r / sqrt(1 - r^2))   # 0.5493 0.2 0.156 0.736 1.1547', python='import math\nfrom metalab import stats as S\nz,v=S.fisher_z(0.5,28); se=math.sqrt(v); print(z,v,math.tanh(z-1.96*se),math.tanh(z+1.96*se),2*.5/math.sqrt(1-.25))'),
 application="**Milestone 7/9:** if your question is about association, specify r vs slope in the protocol; record covariate sets.", checklist=["Effect measure pre-specified","z variance uses n−3","Back-transformation at the end","Conversions documented"],
 quiz=[dict(q="Fisher z for r = 0.5?", opts=["0.549","0.5","0.693","1.155"], ans=0, why="atanh(0.5) = 0.5493.", numeric=True),
  dict(q="Variance of z when n = 28?", opts=["0.04","0.036","0.25","0.5"], ans=0, why="1/(n−3) = 1/25.", numeric=True),
  dict(q="d for r = 0.5 (equal groups)?", opts=["1.155","0.5","0.866","1.0"], ans=0, why="2r/√(1−r²).", numeric=True),
  dict(q="Pooled correlations are best computed by...", opts=["Pooling Fisher z values and back-transforming","Averaging r","Taking the median r","Using the largest study"], ans=0, why="Stabilised variance."),
  dict(q="Adjusted regression slopes from models with different covariates are...", opts=["Not directly comparable without care","Always comparable","Equal to r","Always standardised"], ans=0, why="Different estimands.")])

# ===================================================================== 30
add(id=30, title="Count, rate and survival outcomes", last_verified=V, prerequisites=["Modules 24, 27, 28"],
 objectives=["Choose between a rate ratio, risk ratio, odds ratio and hazard ratio for count and time-to-event data.", "Compute a log incidence rate ratio and its variance, and a log hazard ratio from a reported CI.", "Recognise when event counts, exposure time or censoring change the analysis."],
 why="Lifespan, tumour incidence, mortality, infection and behaviour counts do not behave like continuous measurements. Using a mean-difference or a risk ratio when a rate or hazard is appropriate (or vice versa) misrepresents the data.",
 plain="""**Counts over equal exposure** (e.g. offspring per vial in a fixed period) can be analysed as counts; if exposure time varies, use **rates** (events per unit time). The **incidence rate ratio (IRR)** = (x₁/t₁)/(x₂/t₂); its log has variance ≈ 1/x₁ + 1/x₂ (Poisson). **Time-to-event** outcomes (survival, time to infection) involve **censoring**: some individuals are still alive or lost to follow-up. The **hazard ratio (HR)** compares instantaneous event rates; its log is the usual meta-analysis scale. A **risk ratio** or **odds ratio** at a fixed time point ignores timing.""",
 intermediate="""**Extracting log HR:** from a reported HR and CI, SE(ln HR) = (ln U − ln L)/(2×1.96) (Parmar et al. 1998; Tierney et al. 2007 give methods when only p-values, logrank statistics or curves are available). With the logrank statistics, ln HR ≈ (O − E)/V and variance 1/V. **Overdispersion:** counts with variance greater than the mean (common in biology: vial effects) need quasi-Poisson/negative-binomial thinking at the primary level; if only totals are reported flag the issue. **Median or mean survival** summaries (Module 86) are alternatives when HRs are unavailable, with different assumptions.""",
 advanced="""The proportional-hazards assumption (constant HR over time) often fails; then a single HR is a time-averaged quantity that depends on follow-up length, so pooled HRs from studies with different follow-up are hard to interpret. Restricted mean survival time differences or time-varying HR meta-analysis (e.g. from reconstructed individual data, Guyot et al. 2012) are alternatives needing specialist support. Competing risks change the meaning of 'event' and cannot be handled by simply censoring competing events.""",
 assumptions=["Counts are Poisson-like (or overdispersion is handled upstream).", "Exposure time is measured consistently.", "Censoring is non-informative.", "Proportional hazards when a single HR is pooled."],
 formulas=[dict(name="Log incidence rate ratio", tex=r"\ln IRR=\ln\frac{x_1/t_1}{x_2/t_2},\qquad \mathrm{Var}=\frac1{x_1}+\frac1{x_2}", symbols={"x":"event counts","t":"exposure time"}),
           dict(name="SE of log HR from CI", tex=r"SE(\ln HR)=\frac{\ln U-\ln L}{2\times1.96}", symbols={"L,U":"95% CI limits of the HR"})],
 worked_example="""Group 1: 10 events in 100 person-days; group 2: 15 events in 110 person-days. Rates 0.100 and 0.136; IRR = 0.100/0.1364 = **0.7333**; ln IRR = **−0.3102**, variance 1/10 + 1/15 = **0.1667** (SE 0.408). The CI is wide because few events were observed - counts, not exposure time, drive precision. (Compare the HR extraction in Lesson 86.)""",
 examples=[("Preclinical","Offspring counts per vial; lifespan HRs."),("Clinical","Event rates per 100 person-years."),("Ecology","Predation events per hour."),("Microbiology","Colony counts per plate."),("Public health","Incidence rate ratios.")],
 mistakes=["Treating counts with unequal exposure as comparable.","Pooling OR and HR as if the same.","Ignoring censoring.","Using SD of a count as if Poisson without checking."],
 misconceptions=[("'An HR of 0.5 means survival is doubled.'","It means half the instantaneous hazard at each time, under PH."),("'Counts can be analysed as continuous variables always.'","Only when counts are large and variance is stable.")],
 controversies=["Pooling HRs under non-proportional hazards.", "OR vs RR in common outcomes."],
 decision_tree=[("Event counts with exposure times?","IRR."),("Time-to-event with censoring?","HR (check PH) or RMST."),("Only binary outcome at fixed time?","RR/OR."),("Only curves?","Reconstruction with labelled uncertainty (Module 86).")],
 exercises=["Compute IRR and SE of ln IRR for 20/150 vs 30/160 person-days.", "Extract ln HR and SE for HR 1.3 (95% CI 1.0 to 1.7).", "List three reasons why a single HR may not be pooled across studies."],
 integrity="Record whether effects are rates, risks or hazards; never relabel one as another.", further=["parmar1998","tierney2007","guyot2012","bradburn2007"],
 coding=dict(r='x1 <- 10; t1 <- 100; x2 <- 15; t2 <- 110\nirr <- (x1 / t1) / (x2 / t2); c(irr, log(irr), 1 / x1 + 1 / x2)   # 0.7333 -0.3102 0.1667', python='from metalab import advanced as A\ny,v=A.log_irr(10,100,15,110); print(y, v)'),
 application="**Milestone 7:** decide the primary outcome scale for count/time-to-event data and record exposure time, censoring and follow-up for each study.", checklist=["Rate vs risk vs hazard decided","Exposure time recorded","Censoring handled","PH checked or flagged"],
 quiz=[dict(q="IRR for 10/100 vs 15/110?", opts=["0.733","1.364","0.667","0.5"], ans=0, why="(10/100)/(15/110).", numeric=True),
  dict(q="Variance of ln IRR here?", opts=["0.1667","0.01","0.5","0.25"], ans=0, why="1/10+1/15.", numeric=True),
  dict(q="SE of ln(HR) for HR 0.75 (0.60, 0.94) is about...", opts=["0.1145","0.25","1.96","0.0619"], ans=0, why="(ln0.94−ln0.60)/(2×1.96).", numeric=True),
  dict(q="Censoring means...", opts=["The event was not observed during follow-up for that individual","The data were deleted","The individual died","An outlier"], ans=0, why="Incomplete follow-up."),
  dict(q="A pooled HR assumes...", opts=["Proportional hazards (constant HR over time)","Equal sample sizes","Normal survival times","No events"], ans=0, why="PH assumption.")])

# ===================================================================== 39
add(id=39, title="Multilevel and multivariate meta-analysis", last_verified=V, prerequisites=["Modules 31, 35, 36, 38"],
 objectives=["Recognise dependent effect sizes (several effects per study, shared controls, multiple outcomes) and why ignoring them is wrong.", "Fit and interpret a three-level model (effects within clusters) and a bivariate/multivariate model.", "Report variance components and the model assumptions."],
 why="Real datasets have dependence: several comparisons per paper, multiple labs, several outcomes measured on the same animals. Treating dependent effects as independent understates variances and inflates the evidence.",
 plain="""A **three-level model** adds a layer to the random-effects model: effect size = overall mean + **cluster effect** (e.g. paper or lab; variance σ²_cluster) + **effect-within-cluster** (σ²_effect) + sampling error. It lets effects from the same cluster be more alike than effects from different clusters. A **multivariate model** treats several outcomes per study jointly, with an **unstructured between-study covariance matrix** (variances τ₁², τ₂² and a correlation ρ) and a **within-study covariance** between outcomes.

The **ignore-dependence shortcut** (treating all effects as independent) makes the pooled SE too small; the **average-within-study shortcut** loses information but is simple and valid when the within-study average is meaningful.""",
 intermediate="""**Sampling covariance.** Effects sharing a control group, or outcomes measured on the same individuals, have correlated *sampling errors*. A proper analysis uses a variance-covariance matrix V with the known covariances (or approximations with an assumed within-study correlation, varied in sensitivity analyses). Three-level models with a diagonal V handle clustering of true effects but not sampling covariance; add robust variance estimation (Module 40) as protection. **Estimation:** REML; with few clusters (<10) variance components are poorly determined. **Reporting:** give σ²_cluster, σ²_effect, number of clusters and effects, and the intraclass correlation σ²_cluster/(σ²_cluster + σ²_effect).""",
 advanced="""A multivariate model borrows strength: a study reporting only one of two correlated outcomes still informs the other through the correlation. The between-study correlation is often poorly estimated and hits ±1; a boundary estimate signals that the data cannot support a free correlation (use a simpler structure or a Bayesian prior). Network meta-analysis (Module 42), phylogenetic meta-analysis (shared ancestry as an additional random effect with a known correlation matrix) and dose-response (Module 43) are special cases of the same linear mixed-model machinery. Equivalent formulations exist (hierarchical, structural-equation; Cheung 2014).""",
 assumptions=["True effects within clusters are exchangeable apart from the modelled structure.", "Known (or approximated) sampling covariance.", "Normal random effects.", "Adequate number of clusters for the variance components."],
 formulas=[dict(name="Three-level model", tex=r"y_{ij}=\mu+u_j+e_{ij}+\varepsilon_{ij},\quad u_j\sim N(0,\sigma^2_{c}),\ e_{ij}\sim N(0,\sigma^2_{e}),\ \varepsilon_{ij}\sim N(0,v_{ij})", symbols={"i":"effect","j":"cluster","u":"cluster effect","e":"within-cluster effect","v":"known sampling variance"})],
 worked_example="""Konstantopoulos (2011) multisite trials (published example data in the R package metadat): 56 school effects in 11 districts. REML (metafor `rma.mv`, our code reproduces it to 1e-8 in log-likelihood): overall mean **0.1847**, between-district variance **0.0651**, between-school (within-district) variance **0.0327**; ICC = 0.0651/(0.0651+0.0327) = **0.665**. Berkey et al. (1998) periodontal trials, two correlated outcomes (attachment level and probing depth): pooled changes **−0.339** (AL) and **0.353** (PD) with between-trial correlation **0.609** (metafor `struct="UN"`; reproduced by MetaLab's multivariate function).""",
 examples=[("Preclinical","Several lifespan comparisons from one lab and strain."),("Clinical","Multiple outcomes per trial."),("Ecology","Effects nested in studies nested in species."),("Genetics","Multiple traits per cross."),("Education","Effects within schools within districts.")],
 mistakes=["Treating dependent effects as independent.","Counting the shared control twice.","Fitting a free correlation with 4 studies.","Reporting only the overall mean without variance components."],
 misconceptions=[("'Averaging effects within a study is always wrong.'","It is valid if the average is the target; it loses within-study information."),("'A three-level model fixes shared-control dependence.'","Only sampling covariance modelling does.")],
 controversies=["Approximating sampling covariances with an assumed correlation.", "Multilevel vs robust variance estimation (use both)."],
 decision_tree=[("One effect per study?","Standard model."),("Several effects per cluster, covariance unknown?","Three-level + robust variance."),("Several outcomes per participant?","Multivariate with V."),("<10 clusters?","Warn; consider simpler model and sensitivity analyses.")],
 exercises=["Identify the dependence structure in three published meta-analyses.", "Compute the ICC for σ²_c = 0.04, σ²_e = 0.06.", "Run the Konstantopoulos example in the Statistics Lab and compare the model-based and robust SE."],
 integrity="Declare the dependence structure and the assumed covariance values before looking at results; run sensitivity analyses for assumed correlations.", further=["cheung2014","assink2016","cheung2019","nakagawa2012"],
 coding=dict(r='library(metafor)\nres <- rma.mv(yi, vi, random = ~ 1 | district/school, data = dat.konstantopoulos2011, method = "REML")\nround(c(res$beta, res$sigma2), 4)   # 0.1847 0.0651 0.0327', python='from metalab import advanced as A\nfrom metalab.datasets import KON_YI, KON_VI, KON_DISTRICT\nf = A.multilevel_meta(KON_YI, KON_VI, KON_DISTRICT)\nprint(f["beta"], f["sigma2_cluster"], f["sigma2_effect"])'),
 application="**Milestone 9:** map the dependence structure of your extraction (shared controls, multiple outcomes, nested data) and choose the model before analysis.", checklist=["Dependence structure mapped","Covariance assumptions stated","Variance components reported","Robust variance as backup"],
 quiz=[dict(q="ICC for σ²_cluster = 0.0651 and σ²_effect = 0.0327 is:", opts=["0.665","0.335","0.098","0.5"], ans=0, why="0.0651/0.0978.", numeric=True),
  dict(q="Ignoring dependence typically makes the pooled SE...", opts=["Too small","Too large","Correct","Negative"], ans=0, why="Information is overcounted."),
  dict(q="A between-study correlation of exactly −1 or +1 suggests...", opts=["A boundary estimate; the data cannot identify the correlation","Perfect agreement","A programming error only","Normality"], ans=0, why="Flat likelihood."),
  dict(q="Shared control groups create...", opts=["Correlated sampling errors","Equal variances","No dependence","Bias in the mean"], ans=0, why="The same control data enter two comparisons."),
  dict(q="Which is NOT a multilevel-type structure?", opts=["Independent studies with one effect each","Effects within labs","Several outcomes per trial","Species with shared ancestry"], ans=0, why="Independence.")])

# ===================================================================== 40
add(id=40, title="Robust variance estimation (RVE)", last_verified=V, prerequisites=["Module 39"],
 objectives=["Explain what RVE protects against and what it does not.", "Describe the CR1 and CR2 corrections and Satterthwaite degrees of freedom.", "Choose RVE or a full model when covariance is unknown, and report df."],
 why="RVE lets you obtain valid standard errors for meta-regression coefficients with dependent effect sizes when the exact dependence structure is unknown - a common situation.",
 plain="""RVE (Hedges, Tipton & Johnson 2010) fits a **working model** (often simple) and then computes a **sandwich** variance estimator from the cluster-level residuals, so that standard errors remain approximately valid even if the working model for the dependence is wrong. It needs a **reasonable number of independent clusters** (papers/labs). With few clusters the plain sandwich estimator is biased downward; the small-sample adjustment **CR2** and **Satterthwaite degrees of freedom** (Tipton & Pustejovsky 2015) give much better coverage. **Always report the degrees of freedom**: when df < ~4 the test is unreliable regardless of nominal p.""",
 intermediate="""**Working models.** Efficiency improves if the working model is close to the true covariance structure (Pustejovsky & Tipton 2021), but validity does not depend on it. **What RVE does not fix:** bias from selective reporting, wrong effect-size computation, or a poor working model for the *mean* structure. **Leverage:** moderators that vary only within a few clusters or are unbalanced give small df (<4) even with many effects - the effective sample size is the number of informative clusters, not the number of effects. **Choice of correction:** CR0/CR1 are simple but liberal (too many false positives) with few clusters; use CR2 + Satterthwaite as the default in this setting.""",
 advanced="""CR2 uses adjustment matrices A_j = D_j′ B_j^(−1/2) D_j with B_j = D_j (I − H)_j Φ (I − H)_j′ D_j′ so that the variance estimator is exactly unbiased when the working covariance Φ is correct. The Satterthwaite df for a coefficient is (tr P)²/tr(P²) where P is the matrix of cross-products of the contrast-specific influence vectors. MetaLab's implementation was benchmarked against clubSandwich 0.5.10; the first version omitted a factor in B_j and the benchmark caught it (see corrections log).""",
 assumptions=["Many enough independent clusters (≥ ~10-20; df reported).", "Cluster-independent errors (clusters are the independent units).", "The mean structure is correct."],
 formulas=[dict(name="Sandwich variance (CR family)", tex=r"\hat V_{R}=M\Big(\sum_j X_j' W_j A_j e_j e_j' A_j W_j X_j\Big)M,\qquad M=(X'WX)^{-1}", symbols={"j":"cluster","e_j":"residuals","A_j":"adjustment matrix (identity for CR0)","W_j":"working weights"})],
 worked_example="""Konstantopoulos (2011) data, intercept-only three-level model (11 districts): model-based SE **0.0846**. With **CR2 + Satterthwaite** (clubSandwich 0.5.10 reference): SE **0.0845**, t = **2.187**, df = **9.86**, p = **0.054**. The substantive conclusion changes from 'p < 0.05 by a normal approximation' to 'borderline' once the small number of clusters is accounted for. Reported correctly: 'mean = 0.185, CR2 SE 0.084, 95% CI based on t with 9.9 df'.""",
 examples=[("Preclinical","Effects clustered by lab."),("Clinical","Multiple outcomes per trial."),("Ecology","Effects clustered by species/paper."),("Genetics","Effects from the same cross."),("Education","Effects within schools.")],
 mistakes=["Reporting RVE p-values without df.","Using CR0/CR1 with ten clusters.","Interpreting RVE as a fix for biased effects.","Counting effects rather than clusters."],
 misconceptions=[("'RVE makes any dependence structure irrelevant.'","It protects the SEs, not the efficiency, and not against bias."),("'More effects always means more power.'","Clusters set the effective information.")],
 controversies=["Choice of working model.", "Interpretation of tests with df<4."],
 decision_tree=[("≥ 10-20 clusters and unknown covariance?","RVE with CR2 + Satterthwaite."),("<10 clusters?","Use cautiously; report df; consider simpler models."),("Covariance known?","Fit it directly (Module 39) and use RVE as a check.")],
 exercises=["Explain why df can be small with 100 effects.", "Compare CR0, CR1 and CR2 SE for a small dataset in R (clubSandwich).", "Write the sentence you would put in the methods describing RVE and df."],
 integrity="Report degrees of freedom and the correction used; do not claim significance when df < 4.", further=["hedges2010rve","tipton2015","pustejovsky2021"],
 coding=dict(r='library(metafor)\nres <- rma.mv(yi, vi, random = ~ 1 | district/school, data = dat.konstantopoulos2011)\nround(res$se, 4)   # model-based SE 0.0846\n# CR2: library(clubSandwich); coef_test(res, vcov = "CR2", cluster = dat.konstantopoulos2011$district)', python='from metalab import advanced2 as B\nfrom metalab.datasets import KON_YI, KON_VI, KON_DISTRICT\nr = B.multilevel_cr2(KON_YI, KON_VI, KON_DISTRICT)\nprint(r["se"], r["df"], r["p"])'),
 application="**Milestone 9:** if effects cluster, include RVE with CR2 as the pre-specified robustness check and plan to report df.", checklist=["Clusters counted","CR2 + Satterthwaite used","df reported","Not used to fix bias"],
 quiz=[dict(q="CR2 Satterthwaite df for the Konstantopoulos intercept model (clubSandwich):", opts=["9.86","56","11","1.96"], ans=0, why="Reference value 9.863.", numeric=True),
  dict(q="Which is the main purpose of RVE?", opts=["Valid SEs when the dependence structure is unknown","Removing publication bias","Replacing heterogeneity","Increasing the number of studies"], ans=0, why="Sandwich estimator."),
  dict(q="df < 4 means...", opts=["The test is unreliable; treat as exploratory","The test is exact","The effect is large","More effects are needed"], ans=0, why="Few informative clusters."),
  dict(q="RVE protects against...", opts=["Misspecified dependence in SEs","Selective reporting","Wrong effect sizes","All bias"], ans=0, why="Not bias."),
  dict(q="Effective sample size for RVE is closest to the number of...", opts=["Independent clusters","Effects","Participants","Authors"], ans=0, why="Clusters.")])

# ===================================================================== 41
add(id=41, title="Bayesian meta-analysis", last_verified=V, prerequisites=["Modules 26, 35"],
 objectives=["Explain the Bayesian normal-normal hierarchical model and its priors.", "Choose and justify a prior for the heterogeneity parameter; run a prior sensitivity analysis.", "Report posterior summaries and credible intervals correctly."],
 why="With few studies (the usual situation in laboratory biology), frequentist τ² and CIs are unstable. Bayesian meta-analysis stabilises inference through a prior - provided that prior is transparent and tested.",
 plain="""The model is the usual random-effects model written with priors: yᵢ ~ N(θᵢ, vᵢ), θᵢ ~ N(μ, τ²), with a (usually vague) prior on μ and a **proper weakly informative prior on τ** (e.g. half-normal or half-Cauchy). The result is a **posterior distribution** for μ and τ: a **95% credible interval** is an interval with 95% posterior probability *given the model and prior*. With very few studies the prior on τ can dominate τ inference - so you **must report it and show a sensitivity analysis** with another prior (Röver et al. 2021 discuss weakly informative priors for the heterogeneity parameter).""",
 intermediate="""**Why bother?** (1) A sensible prior avoids the τ² = 0 boundary problem and gives wider, more honest intervals for μ with few studies. (2) The prior can encode external evidence (e.g. typical heterogeneity in your field). (3) Predictive distributions for a new study follow directly. **Priors for τ must be on the effect-size scale:** a half-normal(0.5) prior is plausible for log ratios (most heterogeneity below ~1) but silly for standardised effects with tiny scale. **MCMC vs numerical integration:** for the one-dimensional τ problem with known variances, the posterior can be computed by numerical integration (as in MetaLab's `bayes_meta`, benchmarked against an independent R quadrature); more complex models need MCMC (brms, JAGS, Stan) with convergence diagnostics (R-hat, effective sample size).""",
 advanced="""Posterior summaries: mean/median and equal-tailed credible intervals; HPD intervals can differ for skewed posteriors. Bayes factors for μ = 0 are sensitive to priors on μ and are not recommended as a routine output. **Model checking:** posterior predictive checks, leave-one-out, comparison with frequentist estimates. Bayesian methods do not remove selection bias, dependence or poor data quality; they only change how uncertainty is quantified.""",
 assumptions=["The normal-normal model (known within-study variances, normal random effects).", "The prior is justified, reported and tested.", "Studies are independent (or the dependence is modelled)."],
 formulas=[dict(name="Normal-normal hierarchical model", tex=r"y_i\mid\theta_i\sim N(\theta_i,v_i),\ \theta_i\mid\mu,\tau\sim N(\mu,\tau^2),\ \mu\propto 1,\ \tau\sim \text{half-}N(s)", symbols={"s":"prior scale for tau"})],
 worked_example="""BCG vaccine trials (13 trials, log risk ratio; flat prior on μ, half-normal(0.5) prior on τ; posterior from independent numerical integration in R): posterior **median μ = −0.709, 95% credible interval −1.091 to −0.347**; **median τ = 0.554, 95% credible interval 0.346 to 0.902**. Switching to a half-Cauchy(0.5) prior gives median μ = −0.710 and τ median 0.564: for 13 trials the conclusions are stable, which is exactly what a sensitivity analysis should show.""",
 examples=[("Preclinical","Few studies of a lifespan intervention."),("Clinical","Rare-event meta-analyses."),("Ecology","Prior from earlier meta-analyses."),("Genetics","Small effect-size collections."),("Education","Heterogeneous interventions.")],
 mistakes=["Using a default vague prior for τ without checking.","Reporting a posterior without the prior.","Calling credible intervals 'confidence intervals'.","Ignoring MCMC diagnostics."],
 misconceptions=[("'Bayesian results are prior-free.'","They depend on the prior; with few studies strongly."),("'Bayes factors answer whether the effect is real.'","They are prior-dependent summaries.")],
 controversies=["Default priors for τ.", "Whether to use informative priors from earlier reviews.", "Bayes factors vs estimation."],
 decision_tree=[("k < 5-10?","Bayesian with weakly informative τ prior is attractive; report sensitivity."),("Do you have external information?","Encode as a prior with documentation."),("Complex dependence?","Hierarchical MCMC model with diagnostics.")],
 exercises=["Compare posterior τ under half-normal(0.1) and (2.0) for the BCG data in the Statistics Lab.", "Write a sentence describing the prior and sensitivity analysis for a methods section.", "Explain why the CrI is not a confidence interval."],
 integrity="Always report the priors and a sensitivity analysis; never pick the prior that gives the preferred conclusion.", further=["rover2021","higgins2009pi","veroniki2016"],
 coding=dict(r='# Independent reference used in the MetaLab benchmark (numerical integration over tau)\nlibrary(metafor)\nd <- escalc("RR", ai = tpos, bi = tneg, ci = cpos, di = cneg, data = dat.bcg)\nround(c(rma(d$yi, d$vi, method = "REML")$beta, rma(d$yi, d$vi, method = "REML")$tau2), 4)   # frequentist for comparison', python='from metalab import advanced2 as B, stats as S\nfrom metalab.datasets import BCG\nys, vs = zip(*[S.log_risk_ratio(a, a+b, c, c+d, cc=0.5) for a,b,c,d in BCG])\nr = B.bayes_meta(ys, vs, "halfnormal", 0.5); print(r["mu_median"], r["mu_ci"], r["tau_median"], r["tau_ci"])'),
 application="**Milestone 8/9:** if few studies are expected, pre-specify a Bayesian sensitivity analysis and the prior family.", checklist=["Prior reported","Prior sensitivity done","Credible (not confidence) interval","Diagnostics for MCMC"],
 quiz=[dict(q="Posterior median μ for BCG with half-normal(0.5) prior on τ (R reference):", opts=["−0.709","−0.5","0","−1.5"], ans=0, why="Reference value −0.7092.", numeric=True),
  dict(q="Why must the τ prior be on the effect-size scale?", opts=["Heterogeneity is measured in the same units as the effect","It is a convention","Software requires it","It does not matter"], ans=0, why="τ has the units of the effect."),
  dict(q="A 95% credible interval is...", opts=["An interval with 95% posterior probability given model and prior","The same as a confidence interval","A prediction interval","A p-value"], ans=0, why="Posterior probability."),
  dict(q="With 4 studies, the τ prior is usually...", opts=["Influential on the τ posterior","Irrelevant","Unimportant","Forbidden"], ans=0, why="Little data."),
  dict(q="Bayesian MA removes publication bias.", opts=["False","True","Only with MCMC","Only with informative priors"], ans=0, why="It models uncertainty, not selection.")])

# ===================================================================== 42
add(id=42, title="Network meta-analysis", last_verified=V, prerequisites=["Modules 35, 36, 38, 39"],
 objectives=["Explain direct, indirect and mixed evidence and the transitivity/consistency assumptions.", "Read a league table, P-scores/SUCRA and a network graph, with the caveats.", "Plan an NMA and know when not to do one."],
 why="Where several interventions are compared in different trials, a network meta-analysis can compare them all - but it relies on assumptions that are easy to violate and hard to test with few studies.",
 plain="""Suppose trials compare A vs B and B vs C but none compares A vs C. The **indirect comparison** A vs C = (A vs B) − (B vs C) is valid only if the trials are similar enough in patients/conditions (**transitivity**). A **network meta-analysis (NMA)** combines direct and indirect evidence for all pairs in a connected network (Lu & Ades 2004). **Consistency** means direct and indirect estimates agree; it can be tested, but with few studies the tests are weak. A **league table** shows all pairwise estimates; **P-scores** (frequentist; Rücker & Schwarzer 2015) or **SUCRA** (Bayesian; Salanti et al. 2011) summarise rankings but ignore certainty of evidence, so a high rank is not proof of benefit.""",
 intermediate="""**Mechanics (contrast-based):** within each study, form contrasts against a baseline arm (multi-arm studies have correlated contrasts because they share the baseline: covariance = baseline variance). Estimate basic parameters d(reference→t) by weighted least squares (common effect) or mixed model with a common τ² (random effects; contrasts within a multi-arm study have covariance τ²/2). **Assumptions to assess:** (1) transitivity: effect modifiers (age, sex/strain, dose, follow-up) balanced across comparisons; (2) consistency: node-splitting and design-by-treatment tests (Higgins et al. 2012); (3) a connected network; (4) a single τ² for all comparisons (relaxations exist). **Reporting:** PRISMA-NMA (Hutton et al. 2015); certainty via CINeMA/GRADE-NMA. **MetaLab implements** the estimation, league table, P-scores and global Q; node-splitting, design-by-treatment tests and component NMA are NOT implemented (use netmeta/gemtc: see `validation/external_workflows/01_netmeta.R`).""",
 advanced="""Sparse networks and star-shaped designs (everything compared to placebo) provide almost no loop-based inconsistency information. Multi-arm studies must be modelled with their correlations; ignoring them double-counts the baseline arm. P-scores and SUCRA are functions of point estimates and standard errors; with wide intervals, ranks are unstable and a 'best' treatment can be indistinguishable from the next. Network meta-regression and component NMA address effect modification and complex interventions but need many studies.""",
 assumptions=["Transitivity (effect modifiers similar across comparisons).", "Consistency of direct and indirect evidence.", "Connected network.", "Common τ² (default).", "Arm-level data are independent within study."],
 formulas=[dict(name="Contrast-based NMA (common effect)", tex=r"y_{s}=X_s d+\varepsilon_s,\quad \hat d=(X'V^{-1}X)^{-1}X'V^{-1}y", symbols={"d":"basic parameters vs reference","V":"within-study covariance (shared baseline)"})],
 worked_example="""Hasselblad (1998) smoking-cessation network (24 studies, 4 interventions; log odds, 0.5 added to every cell): random-effects ORs versus no contact - individual counselling **1.99**, group counselling **2.33**, self-help **1.48**; τ² = **0.432**; global Q = 202.3 (df 23). P-scores (cessation: higher OR better): no contact 0.04, self-help ≈ 0.40, individual counselling 0.71, group counselling 0.85 (computed by MetaLab, which makes the ranking direction an explicit required argument). The very large Q (202 on 23 df) signals heterogeneity/inconsistency that a real analysis must investigate; ranks with such heterogeneity should not be over-interpreted. The estimates reproduce metafor `rma.mv` (benchmark), NOT netmeta (not installable in the build environment).""",
 examples=[("Preclinical","Several compounds compared against vehicle in different cohorts."),("Clinical","Multiple drugs for one condition."),("Ecology","Management interventions."),("Genetics","Multiple edits/guides."),("Education","Teaching methods.")],
 mistakes=["Ignoring transitivity.","Ranking by P-score without intervals.","Treating multi-arm studies as independent.","Running an NMA with a disconnected network."],
 misconceptions=[("'NMA creates randomised comparisons where none exist.'","Indirect comparisons are observational in nature across trials."),("'SUCRA = probability of being best.'","It is a mean rank-based summary.")],
 controversies=["Rankings vs certainty of evidence.", "Testing inconsistency with few studies.", "Common vs treatment-specific τ²."],
 decision_tree=[("Treatments never compared head-to-head but linked by common comparators?","NMA possible; assess transitivity."),("Effect modifiers imbalanced across comparisons?","Do not pool; use meta-regression or stop."),("Disconnected network?","Separate analyses.")],
 exercises=["Draw the network graph for a published NMA and list effect modifiers.", "Compute the indirect OR A vs C from A vs B = 1.5 and B vs C = 0.8 and its variance rule.", "Explain why P-scores can mislead."],
 integrity="State the ranking direction and show uncertainty; never present a ranking as a recommendation without certainty-of-evidence assessment.", further=["lu2004","rucker2015pscore","higgins2012incons","salanti2011","hutton2015"],
 coding=dict(r='# netmeta workflow (run locally): see validation/external_workflows/01_netmeta.R\n# metafor route used for the MetaLab benchmark: contrast data + rma.mv(yi, V, mods = X, random = ~ comp | study, struct = "CS", rho = 1/2)', python='import numpy as np\nfrom metalab import advanced2 as B, datasets as DS\nar = DS.HASSELBLAD; x = np.array([a[2] for a in ar], float); n = np.array([a[3] for a in ar], float)\nr = B.nma([a[0] for a in ar], [a[1] for a in ar], np.log((x+.5)/(n-x+.5)), 1/(x+.5)+1/(n-x+.5), reference="no_contact", model="random", higher_is_better=True)\nprint(np.exp(r["beta"]), r["tau2"], r["pscore"])'),
 application="**Milestone 9:** only if your review question compares ≥3 interventions; first write down the effect modifiers and tabulate them across comparisons.", checklist=["Transitivity assessed","Network connected","Multi-arm handled","Ranking direction stated","Certainty assessed"],
 quiz=[dict(q="Random-effects OR, individual counselling vs no contact (Hasselblad):", opts=["1.99","0.50","2.33","1.48"], ans=0, why="exp(0.686).", numeric=True),
  dict(q="Transitivity means...", opts=["Effect modifiers are similar across the compared sets of studies","Studies are of the same size","Results are significant","The network is a star"], ans=0, why="Indirect comparisons need similar populations."),
  dict(q="Multi-arm studies require...", opts=["Accounting for the correlation between contrasts sharing the baseline","Deleting them","Ignoring one arm","Independent contrasts"], ans=0, why="Shared baseline variance."),
  dict(q="A high P-score alone means...", opts=["High mean certainty-ignoring rank; not proof of benefit","Proven best","Significant","Causal"], ans=0, why="Ranks ignore certainty."),
  dict(q="Which is NOT implemented in MetaLab?", opts=["Node-splitting inconsistency tests","League table","Contrast construction","P-scores"], ans=0, why="Use netmeta for node-splitting.")])

# ===================================================================== 43
add(id=43, title="Dose-response meta-analysis", last_verified=V, prerequisites=["Modules 29, 39"],
 objectives=["Explain why category-level dose-response data produce correlated estimates.", "Describe the Greenland-Longnecker approach and one-/two-stage dose-response models.", "Know the limits of linear-trend summaries and the need for an external R workflow."],
 why="Exposure-outcome relationships (concentration, dose, age, temperature) are often reported in dose categories relative to a reference. Treating each category's effect as independent ignores that they share the reference group.",
 plain="""Studies often report relative risks (or log RRs) for several exposure levels against one **reference category**. Because every non-reference estimate shares the reference group's data, the estimates are **correlated**. Greenland & Longnecker (1992) showed how to reconstruct the approximate covariance matrix from the cases and non-cases per category and then estimate a **trend (slope)** that accounts for it. A **two-stage** approach estimates a dose-response curve per study (linear or spline) with its covariance and pools the coefficients; **one-stage** mixed models fit all studies jointly. Orsini et al. (2012) describe approximations and linear vs non-linear fits and software.""",
 intermediate="""**Inputs needed per study:** doses (midpoints of categories; open-ended categories need an assumption), effect estimates with SEs/CIs, and cases/person-time (or n) per category to reconstruct covariances. **Curve shape:** linear trend is simple but can hide non-linearity; restricted cubic splines (3-4 knots) are standard; compare shapes and report the shape assumption. **Heterogeneity** is across studies' curves, not points. **Pitfalls:** dose categories on different scales/units across studies; adjusting variables differing across studies; extrapolating beyond observed doses; using a single naive trend (ignoring the correlation) gives biased CIs. In biological dose-response (e.g. compound concentration vs lifespan) similar logic applies but typical data are continuous outcomes per dose group and can be analysed with meta-regression on dose when the same reference (control) is shared - a shared-control covariance matrix is required.""",
 advanced="""MetaLab does **not** implement dose-response meta-analysis; no benchmark against dosresmeta was possible because the package could not be installed in the build environment. This lesson explains the method and the R workflow (`validation/external_workflows/04_dosresmeta.R`, an UNVERIFIED sketch to be checked against the package vignette). Reference-category choice and the treatment of cases/non-cases for covariance reconstruction materially affect results; sensitivity analyses vary the knots, the reference category and the dose midpoint assumptions.""",
 assumptions=["Dose midpoints or assigned values are reasonable.", "The dose-response shape (linear/spline) is adequate.", "Covariances reconstructed from marginal data are adequate approximation.", "Comparable adjustment sets across studies."],
 formulas=[dict(name="Naive weighted slope through the reference (illustration only; ignores correlation)", tex=r"\hat\beta=\frac{\sum d_i y_i/v_i}{\sum d_i^2/v_i}", symbols={"d":"dose relative to reference","y":"log relative risk","v":"variance"})],
 worked_example="""Illustration only (NOT the Greenland-Longnecker estimator): doses 0, 1, 2 with log RR 0, 0.20, 0.50 and variances 0.04 each for the non-reference categories. The naive weighted slope through the origin is Σ dy/v / Σ d²/v = (1×0.2/0.04 + 2×0.5/0.04)/(1/0.04 + 4/0.04) = (5 + 25)/(25 + 100) = **0.24** per dose unit. Because the two non-reference estimates share the reference group, their covariance is positive and ignoring it misstates the variance of the slope - the reason a covariance-aware method is required.""",
 examples=[("Preclinical","Compound concentration vs lifespan."),("Clinical","Alcohol dose vs risk."),("Ecology","Temperature response curves."),("Genetics","Copy number vs phenotype."),("Nutrition","Intake vs outcome.")],
 mistakes=["Treating categories as independent.","Using category labels instead of dose values.","Ignoring non-linearity.","Extrapolating outside the data."],
 misconceptions=[("'Higher categories always show higher risk.'","Curves may be J-shaped or plateau."),("'The p-trend proves causality.'","Trend tests do not address confounding.")],
 controversies=["Spline vs linear summaries.", "Handling open-ended categories.", "One-stage vs two-stage."],
 decision_tree=[("Category data with a reference group?","Greenland-Longnecker covariance + dosresmeta/other."),("Individual dose per participant?","Standard meta-regression."),("Non-linear?","Splines; report shape sensitivity.")],
 exercises=["Define doses and reference categories for a dataset from your area.", "Explain why category estimates are correlated.", "List the inputs needed to reconstruct covariances."],
 integrity="State shape assumptions and the dose assignment rule; do not use the naive independent-variance slope for inference.", further=["greenland1992","orsini2012","borenstein2009book"],
 coding=dict(r='# Illustration only (naive slope; NOT a substitute for dosresmeta)\nd <- c(1, 2); y <- c(0.20, 0.50); v <- c(0.04, 0.04)\nsum(d * y / v) / sum(d^2 / v)   # 0.24', python='d=[1,2]; y=[0.20,0.50]; v=[0.04,0.04]\nprint(sum(a*b/c for a,b,c in zip(d,y,v))/sum(a*a/c for a,c in zip(d,v)))'),
 application="**Milestone 9:** if your question is dose-response, plan the covariance approach and software (external R workflow) before extraction.", checklist=["Reference category defined","Dose values assigned","Covariance method chosen","Shape sensitivity planned"],
 quiz=[dict(q="The naive weighted slope in the worked example equals:", opts=["0.24","0.35","0.5","0.2"], ans=0, why="(5+25)/(25+100).", numeric=True),
  dict(q="Non-reference category estimates from one study are correlated because...", opts=["They share the reference group","They share the p-value","They have equal variance","They are percentages"], ans=0, why="Common reference."),
  dict(q="Greenland-Longnecker is used to...", opts=["Reconstruct the covariance among category estimates and estimate a trend","Estimate publication bias","Compute I²","Convert medians"], ans=0, why="Method purpose."),
  dict(q="Is dose-response MA implemented in MetaLab?", opts=["No - lesson + external R workflow only","Yes, fully","Only for lifespan","Only Bayesian"], ans=0, why="Honest status."),
  dict(q="Extrapolating a dose-response curve beyond observed doses is...", opts=["Unsupported by the data","Recommended","Required","Always valid"], ans=0, why="No data.")])

# ===================================================================== 44
add(id=44, title="Diagnostic test accuracy meta-analysis", last_verified=V, prerequisites=["Modules 29, 39"],
 objectives=["Compute sensitivity, specificity, DOR and likelihood ratios from a 2×2 table.", "Explain the bivariate (Reitsma) model and why sensitivity and specificity are modelled jointly.", "Appraise DTA studies with QUADAS-2 and report with PRISMA-DTA."],
 why="Diagnostic questions (does this assay detect disease?) need accuracy measures; pooling sensitivity and specificity separately ignores their threshold-driven correlation and misleads.",
 plain="""Each study provides a 2×2 table: TP, FN (diseased) and FP, TN (non-diseased). **Sensitivity** = TP/(TP + FN), **specificity** = TN/(TN + FP). Studies use different thresholds, so sensitivity and specificity trade off: a **negative correlation** between logit(sens) and logit(spec) across studies is expected. The **bivariate model** (Reitsma et al. 2005) models logit(sens) and logit(spec) as a bivariate normal across studies with a covariance, producing summary sensitivity and specificity, and their correlation. The **HSROC model** is an equivalent reparametrisation in the common case without covariates. Derived summaries: **DOR** = (TP×TN)/(FN×FP); **LR+ = sens/(1 − spec)**; **LR− = (1 − sens)/spec**.""",
 intermediate="""**Study quality:** QUADAS-2 (Whiting et al. 2011) assesses risk of bias (patient selection, index test, reference standard, flow and timing) and applicability. **Reporting:** PRISMA-DTA (McGrath et al. 2019). **Practicalities:** continuity corrections for zero cells (0.5 added to all cells here), choice of threshold per study, **spectrum bias** (case-control designs overstate accuracy), partial verification, and heterogeneity explained by covariates (test type, setting) via meta-regression on the bivariate model. Summary points apply to a 'typical' study/threshold; they are not a property of the test alone. **MetaLab implements** the bivariate model for summary points (benchmarked against metafor `rma.mv` on a SYNTHETIC table); SROC curves/HSROC and comparisons between tests are not implemented (mada; `validation/external_workflows/02_mada_dta.R`).""",
 advanced="""With few studies the between-study correlation is estimated at ±1 (boundary); simplify the structure or use Bayesian priors. Prevalence differs between studies, so predictive values should not be pooled directly - compute them from pooled sens/spec at a stated prevalence. Test-comparison reviews need direct (within-study) comparisons to avoid confounding. Imperfect reference standards bias accuracy estimates in a direction depending on error correlation.""",
 assumptions=["Studies used comparable thresholds or modelled threshold effects.", "Logit-transformed sens/spec are approximately bivariate normal across studies.", "The reference standard is adequate.", "Independent studies."],
 formulas=[dict(name="Diagnostic summary measures", tex=r"Se=\frac{TP}{TP+FN},\ Sp=\frac{TN}{TN+FP},\ DOR=\frac{TP\cdot TN}{FN\cdot FP},\ LR^+=\frac{Se}{1-Sp},\ LR^-=\frac{1-Se}{Sp}", symbols={"TP,FN,FP,TN":"2x2 table cells"})],
 worked_example="""One study: TP = 45, FN = 5, FP = 8, TN = 92. Sensitivity = 45/50 = **0.90**; specificity = 92/100 = **0.92**; DOR = (45×92)/(5×8) = **103.5**; LR+ = 0.90/0.08 = **11.25**; LR− = 0.10/0.92 = **0.1087**. For the **synthetic** 12-study table in `datasets.DTA_SYNTHETIC` (simulated with a fixed seed, NOT real studies) the bivariate REML model gives summary sensitivity **0.813**, summary specificity **0.910** and a between-study correlation of **−0.316**, matching metafor `rma.mv` to the tolerances asserted in the tests (the dedicated package mada was not available).""",
 examples=[("Preclinical","Biomarker assays vs histology."),("Clinical","Imaging tests."),("Microbiology","Rapid pathogen tests."),("Genetics","Variant calling vs sequencing reference."),("Education","Screening instruments.")],
 mistakes=["Pooling sensitivity and specificity separately.","Pooling predictive values across studies with different prevalence.","Ignoring threshold differences.","Case-control designs treated as cohort."],
 misconceptions=[("'High DOR means a good test at every threshold.'","DOR is threshold-independent but clinically uninformative about sens/spec trade-offs."),("'Specificity and sensitivity are fixed properties of a test.'","They depend on threshold and population.")],
 controversies=["Bivariate vs HSROC.", "Handling imperfect reference standards.", "Test comparison with indirect evidence."],
 decision_tree=[("2×2 tables available?","Bivariate model."),("Few studies (<5)?","Simplify correlation; caveat."),("Compare tests?","Within-study comparisons preferred."),("Threshold varies?","Model threshold; do not pool blindly.")],
 exercises=["Compute Se, Sp, DOR, LR+ and LR− for TP 30, FN 10, FP 6, TN 64.", "Explain spectrum bias.", "Complete a QUADAS-2 table for one published study."],
 integrity="Report thresholds, reference standards and QUADAS-2 judgements; never present summary sens/spec without their CIs and the between-study correlation.", further=["reitsma2005","whiting2011","mcgrath2019dta"],
 coding=dict(r='tp <- 45; fn <- 5; fp <- 8; tn <- 92\nse <- tp / (tp + fn); sp <- tn / (tn + fp)\nc(se, sp, tp * tn / (fn * fp), se / (1 - sp), (1 - se) / sp)   # 0.90 0.92 103.5 11.25 0.1087', python='tp,fn,fp,tn=45,5,8,92; se=tp/(tp+fn); sp=tn/(tn+fp)\nprint(se, sp, tp*tn/(fn*fp), se/(1-sp), (1-se)/sp)'),
 application="**Milestone 7:** for DTA, extract 2×2 tables at the threshold used and record the reference standard, spectrum and verification.", checklist=["2x2 tables extracted","Thresholds recorded","QUADAS-2 completed","Bivariate model planned"],
 quiz=[dict(q="DOR for TP 45, FN 5, FP 8, TN 92:", opts=["103.5","11.25","0.9","8.4"], ans=0, why="(45×92)/(5×8).", numeric=True),
  dict(q="LR+ for sensitivity 0.90 and specificity 0.92:", opts=["11.25","0.109","0.98","1.0"], ans=0, why="0.90/0.08.", numeric=True),
  dict(q="Why model sens and spec jointly?", opts=["They are correlated through the threshold","They are equal","They are independent","To get a p-value"], ans=0, why="Threshold effect."),
  dict(q="Predictive values should be pooled by...", opts=["Computing them from pooled sens/spec at a stated prevalence","Averaging directly","Using the largest study","Ignoring prevalence"], ans=0, why="Prevalence-dependent."),
  dict(q="QUADAS-2 assesses...", opts=["Risk of bias and applicability in DTA studies","Heterogeneity","Publication bias","Effect sizes"], ans=0, why="Whiting 2011.")])

# ===================================================================== 45
add(id=45, title="Prognostic and prediction model synthesis", last_verified=V, prerequisites=["Modules 29, 35, 44"],
 objectives=["Distinguish prognostic factor, prognostic model and diagnostic model studies.", "Extract and meta-analyse discrimination (C-statistic) and calibration measures with appropriate transformations.", "Use CHARMS and PROBAST for data extraction and risk-of-bias appraisal."],
 why="Prediction models are often developed on small datasets and reported optimistically; a synthesis must separate model development from external validation and judge bias with a purpose-built tool.",
 plain="""A **prognostic factor** study asks whether a variable is associated with an outcome (e.g. hazard ratio per unit); a **prognostic model** combines predictors to predict the outcome; a **diagnostic model** predicts the current presence of a condition. A synthesis of **model performance** pools **discrimination** (C-statistic/AUC; probability that a model ranks a random event above a non-event) and **calibration** (observed/expected ratio, calibration slope) from **external validations** (not from the development data, which are optimistic). Use **CHARMS** (Moons et al. 2014) for extraction and **PROBAST** (Wolff et al. 2019) for risk of bias and applicability; PROGRESS (Riley et al. 2013) frames prognostic factor research.""",
 intermediate="""**Meta-analysing C-statistics:** transform to logit(c) with SE(logit c) ≈ SE(c)/(c(1 − c)) (delta method), pool with random effects, back-transform; reconstruct SEs from CIs when needed. **Calibration:** pool ln(O/E) and the calibration slope; examine heterogeneity by setting and case-mix. **Heterogeneity is expected** (case-mix, baseline risk, measurement differences) and prediction intervals for model performance in a new setting are more relevant than the mean (Module 35). **Common problems:** overfitting, small event numbers per predictor, categorising continuous predictors, ignoring missing data, and no external validation.""",
 advanced="""Quantifying added value (e.g. net benefit, decision curves) requires patient-level data; summary-level synthesis mostly handles discrimination and calibration. Predictor effects from different adjustment sets are not interchangeable (Module 29). IPD meta-analysis (Module 46) allows internal-external cross-validation across studies. MetaLab provides no prediction-model-specific code beyond transformations and general meta-analysis; this lesson is methodology and extraction guidance.""",
 assumptions=["Performance measures come from validation (not development) samples.", "The delta-method SE for logit(c) is adequate.", "Comparable outcome and prediction horizon."],
 formulas=[dict(name="Logit transform of the C-statistic", tex=r"\operatorname{logit}(c)=\ln\frac{c}{1-c},\qquad SE_{\operatorname{logit}(c)}\approx\frac{SE_c}{c(1-c)}", symbols={"c":"C-statistic","SE_c":"its standard error"})],
 worked_example="""An external validation reports C = 0.75 with SE 0.02. logit(0.75) = **1.0986**; SE on the logit scale = 0.02/(0.75×0.25) = **0.1067**. Pool such values from several validations by random effects and back-transform with c = exp(L)/(1 + exp(L)). Note the C-statistic's limited range: a pooled C of 0.75 with prediction interval 0.62-0.84 says more about expected performance in a new setting than the pooled mean alone.""",
 examples=[("Preclinical","Biomarker-based survival prediction."),("Clinical","Cardiovascular risk scores."),("Ecology","Species distribution models."),("Genetics","Polygenic risk scores."),("Education","Dropout prediction models.")],
 mistakes=["Pooling development-sample performance.","Ignoring calibration.","Ignoring PROBAST bias.","Pooling C-statistics on the raw scale without checking SE."],
 misconceptions=[("'A high C-statistic means clinically useful.'","Calibration and decision impact matter."),("'More predictors always improve a model.'","Overfitting.")],
 controversies=["Meta-analysing C on raw vs logit scale.", "Use of net benefit in synthesis."],
 decision_tree=[("Prognostic factor?","Pool adjusted HRs per unit with covariate-set caveats."),("Prediction model validations?","Pool logit C + ln(O/E)."),("Development only?","Descriptive review, not pooled performance.")],
 exercises=["Compute the logit and SE for C = 0.80, SE = 0.03.", "List the four PROBAST domains.", "Explain why development-sample performance is optimistic."],
 integrity="Never mix development and validation performance in one pooled estimate.", further=["wolff2019probast","moons2014charms","riley2013progress"],
 coding=dict(r='c <- 0.75; se <- 0.02\nL <- qlogis(c); c(L, se / (c * (1 - c)))   # 1.0986 0.1067', python='import math\nc,se=0.75,0.02; print(math.log(c/(1-c)), se/(c*(1-c)))'),
 application="**Milestone 7:** if you review prediction models, use CHARMS for extraction and PROBAST for risk of bias from the start.", checklist=["Validation vs development separated","CHARMS used","PROBAST used","Calibration extracted"],
 quiz=[dict(q="logit(0.75) =", opts=["1.099","0.75","0.5","2.0"], ans=0, why="ln(3).", numeric=True),
  dict(q="SE of logit(c) for c = 0.75, SE_c = 0.02:", opts=["0.1067","0.02","0.75","0.5"], ans=0, why="0.02/0.1875.", numeric=True),
  dict(q="Which data should pooled model performance come from?", opts=["External validation samples","Development samples only","Any","Simulations only"], ans=0, why="Optimism in development."),
  dict(q="PROBAST is used for...", opts=["Risk of bias and applicability of prediction model studies","Heterogeneity","Search","Effect sizes"], ans=0, why="Wolff 2019."),
  dict(q="CHARMS supports...", opts=["Data extraction in prediction-model reviews","Network meta-analysis","DTA pooling","Cluster adjustment"], ans=0, why="Moons 2014.")])

# ===================================================================== 46
add(id=46, title="Individual participant data (IPD) meta-analysis", last_verified=V, prerequisites=["Modules 35, 39"],
 objectives=["Explain when IPD offers advantages over aggregate-data meta-analysis.", "Distinguish one-stage and two-stage IPD models and the need to stratify by study.", "Plan data sharing, harmonisation and reporting (PRISMA-IPD)."],
 why="IPD (participant-level data from each study) allows consistent analysis, time-to-event modelling, subgroup effects within trials and checks of data quality - but it is expensive and requires data-sharing agreements.",
 plain="""In a **two-stage** IPD meta-analysis you analyse each study's participants with the same model (e.g. regression of outcome on treatment) to obtain a study-specific effect and SE, then pool these as in a standard meta-analysis. In a **one-stage** analysis you fit a single mixed model to all participants, **stratifying by study** (separate intercepts per study) with random treatment effects. Properly done, both give similar answers for simple effects; one-stage models are more flexible (rare events, non-linear effects) but need care to avoid treating studies as one big trial (Riley et al. 2010 describe rationale, conduct and reporting; PRISMA-IPD: Stewart et al. 2015).""",
 intermediate="""**Advantages:** consistent definitions and adjustment; time-to-event analysis from raw data; **within-study** interaction (treatment × covariate) separated from **across-study** associations (avoiding ecological bias); checks of randomisation and data errors; non-reported outcomes. **Challenges:** obtaining the data (not all studies share), harmonising variables, privacy/governance, resources. **Bias if studies are missing:** IPD from a non-random subset of studies may be biased - compare with aggregate results from the unavailable studies. **Interaction analyses:** estimate within-study interactions, pool them, and do not rely on between-study meta-regression for patient-level effect modification.""",
 advanced="""One-stage models need decisions on random vs common residual variance, random vs stratified intercepts/slopes and convergence; sensitivity to these choices should be reported. Binary outcomes with rare events may need exact or Firth-type methods. MetaLab implements only a **two-stage** helper (per-study OLS + REML pooling), benchmarked against base R `lm` + metafor; the one-stage lme4 workflow is provided as tested R code (simulated data). Data-governance details (consent, anonymisation, data-use agreements) are essential and outside the software.""",
 assumptions=["Studies are analysed with the same model.", "Treatment effect is approximately normal in each study.", "Between-study heterogeneity random effects normal.", "Studies obtained are representative of all eligible."],
 formulas=[dict(name="One-stage model (stratified intercepts, random treatment effect)", tex=r"y_{ij}=\alpha_j+(\theta+b_j)\,t_{ij}+\varepsilon_{ij},\quad b_j\sim N(0,\tau^2)", symbols={"j":"study","i":"participant","\\alpha_j":"study-specific intercept","t":"treatment indicator"})],
 worked_example="""Simulated IPD (6 studies, 510 participants; seed 42; true mean effect ≈ 0.5): two-stage pooled effect **0.5166** (SE 0.1895, τ² 0.1683), one-stage mixed model (lme4, REML) fixed treatment effect **0.5163**. The tiny difference (0.0003) illustrates that for a continuous outcome and a single treatment effect the two approaches agree closely; the choice matters for rare events, non-linear effects and interactions. The data are SIMULATED for teaching; no real participants.""",
 examples=[("Preclinical","Raw lifespan data from several labs."),("Clinical","Trial participant data."),("Ecology","Raw observations across sites."),("Genetics","Genotype-phenotype records."),("Education","Student-level assessments.")],
 mistakes=["Pooling participants as if from one trial.","Using between-study associations to infer patient-level effects.","Ignoring missing studies.","No data-sharing governance."],
 misconceptions=[("'IPD always gives different answers.'","For simple effects it agrees with aggregate data when done right."),("'IPD removes publication bias.'","Only if all eligible studies contribute.")],
 controversies=["One-stage vs two-stage.", "Handling missing IPD studies."],
 decision_tree=[("Need participant-level effects or time-to-event?","IPD."),("Data obtainable?","Check agreements early."),("Not all studies shared?","Compare with aggregate for missing studies.")],
 exercises=["Simulate IPD for 5 studies and compare one- and two-stage estimates.", "List the variables you would need to harmonise.", "Write a data-sharing request outline (do not send without owner approval)."],
 integrity="Respect data-sharing agreements and privacy; never contact data owners without the review lead's approval (the app never does).", further=["riley2010ipd","stewart2015","tierney2007"],
 coding=dict(r='# One-stage vs two-stage (simulated data); lme4 workflow in validation/external_workflows/06_ipd_one_stage.R\nlibrary(metafor)\nset.seed(1); d <- data.frame(s = rep(1:4, each = 40), t = rep(0:1, 80)); d$y <- rnorm(160) + 0.4 * d$t\nest <- sapply(1:4, function(i) coef(lm(y ~ t, d[d$s == i, ]))["t"]); se <- sapply(1:4, function(i) summary(lm(y ~ t, d[d$s == i, ]))$coefficients["t", 2])\nround(rma(est, se^2, method = "REML")$beta, 3)', python='from metalab import advanced2 as B\nimport numpy as np\nrng=np.random.default_rng(1); s=np.repeat(np.arange(4),40); g=np.tile([0,1],80); y=rng.normal(size=160)+0.4*g\nprint(B.ipd_two_stage(s,g,y)["pooled"].est)'),
 application="**Milestone 9:** decide early whether IPD requests are realistic; they are slow and need governance.", checklist=["Data-sharing feasible","Stratification by study","Within-study interactions","PRISMA-IPD"],
 quiz=[dict(q="Two-stage pooled effect in the simulated IPD (6 studies):", opts=["0.517","0.25","1.0","0.05"], ans=0, why="Reference 0.5166.", numeric=True),
  dict(q="One-stage models must...", opts=["Stratify by study (separate intercepts)","Ignore the study","Use one intercept","Delete heterogeneity"], ans=0, why="Avoid treating data as one trial."),
  dict(q="Why separate within-study and across-study effects?", opts=["Avoid ecological bias","To increase n","To get a p-value","Software requirement"], ans=0, why="Different estimands."),
  dict(q="IPD requires...", opts=["Participant-level data from studies","Only published means","A random sample of authors","Only registries"], ans=0, why="Definition."),
  dict(q="Missing IPD studies can cause...", opts=["Bias if non-random","No problem","Perfect results","Larger n"], ans=0, why="Selection.")])

# ===================================================================== 47
add(id=47, title="Prevalence and incidence meta-analysis", last_verified=V, prerequisites=["Modules 24, 35"],
 objectives=["Choose and justify a transformation for proportions (raw, logit, Freeman-Tukey double arcsine).", "Compute variances for each transformation and back-transform correctly.", "Interpret heterogeneity and prediction intervals for prevalence."],
 why="Prevalence reviews (proportion of animals with a phenotype, infection rates, mutation frequencies) have skewed distributions and variance tied to the mean; naive pooling is biased near 0 or 1.",
 plain="""For x events among n, the raw proportion p = x/n has variance p(1 − p)/n, which approaches 0 as p → 0 or 1; pooling on the raw scale violates normality. Common transformations: **logit** (ln(p/(1 − p)); variance 1/x + 1/(n − x)), **Freeman-Tukey double arcsine** (variance 1/(n + 0.5)), **arcsine** and **raw**. Pool on the transformed scale (random effects), back-transform the pooled value and CI. Barendregt et al. (2013) discuss the logit and double arcsine; they argue for the double arcsine in the MetaXL setting, while other authors recommend logit or GLMM approaches - state and justify your choice, and compare.""",
 intermediate="""**Back-transformation traps:** the double-arcsine back-transformation depends on a single harmonic-mean n; it can give impossible or misleading values and is not recommended for all situations. Logit requires a continuity correction for 0% or 100% (or a GLMM that handles zeros). **Heterogeneity is usually extreme** (I² > 90%) because prevalence differs genuinely across populations; focus on prediction intervals and subgroups; a single pooled prevalence rarely describes a new population. **Incidence:** use rates with person-time (Module 30). **Case definition, sampling frame and diagnostic test** are major sources of heterogeneity.""",
 advanced="""GLMM (binomial-normal) avoids transformations and handles zeros; it needs more computation and expertise (not implemented in MetaLab; metafor `rma.glmm`, meta `metaprop`). Survey-weighted/representativeness issues, repeated measures within studies, and temporal trends complicate pooling. Always report the transformation, back-transformation method and the sensitivity to it.""",
 assumptions=["Studies sample comparable populations or heterogeneity is modelled.", "Proportions are from independent observations.", "Transformation variance approximations hold (not for tiny n)."],
 formulas=[dict(name="Transformations of a proportion", tex=r"\text{logit: } \ln\frac{x}{n-x},\ \frac1x+\frac1{n-x};\qquad \text{FT: } \tfrac12\left[\arcsin\sqrt{\tfrac{x}{n+1}}+\arcsin\sqrt{\tfrac{x+1}{n+1}}\right],\ \frac1{4n+2}", symbols={"x":"events","n":"sample size"})],
 worked_example="""x = 12, n = 80: raw p = **0.15** (variance 0.001594). Logit = ln(0.15/0.85) = **−1.7346**, variance 1/12 + 1/68 = **0.09804**. Freeman-Tukey (metafor's PFT scale) = **0.4036**, variance 1/(4n + 2) = **0.003106**. Pooling is done on the chosen scale; back-transformation of −1.7346 gives exp/(1 + exp) = 0.15.""",
 examples=[("Preclinical","Proportion of flies carrying a mutation."),("Clinical","Disease prevalence."),("Ecology","Occupancy."),("Genetics","Allele frequency."),("Microbiology","Resistance prevalence.")],
 mistakes=["Pooling raw proportions near 0/1.","Back-transforming Freeman-Tukey with arbitrary n.","Ignoring extreme heterogeneity.","Pooling different case definitions."],
 misconceptions=[("'One pooled prevalence describes any population.'","Prevalence is context-dependent."),("'Double arcsine is always best.'","Debated; compare with logit/GLMM.")],
 controversies=["Double arcsine vs logit vs GLMM.", "Reporting a single pooled prevalence."],
 decision_tree=[("Few zeros, moderate p?","Logit."),("Many zeros/extremes?","GLMM or compare transformations."),("Heterogeneous?","Report PI and subgroups.")],
 exercises=["Compute logit, FT and raw variances for 3/40.", "Pool three proportions in the Statistics Lab on two scales.", "Explain why I² is huge in prevalence reviews."],
 integrity="State the transformation and back-transformation; show sensitivity to it.", further=["barendregt2013","borenstein2009book","inthout2016"],
 coding=dict(r='library(metafor)\nd <- escalc(measure = "PLO", xi = 12, ni = 80); round(c(d$yi, d$vi), 4)   # -1.7346 0.0980\nd2 <- escalc(measure = "PFT", xi = 12, ni = 80); round(c(d2$yi, d2$vi), 4)   # 0.4036 0.0031', python='from metalab import advanced as A\nprint(A.proportion_es(12,80,"PLO"), A.proportion_es(12,80,"PFT"))'),
 application="**Milestone 9:** prevalence questions need a case definition and sampling frame recorded for each study.", checklist=["Transformation chosen","Back-transform documented","Heterogeneity explored","Case definition recorded"],
 quiz=[dict(q="Logit of 12/80:", opts=["−1.735","0.15","−0.15","1.9"], ans=0, why="ln(0.15/0.85).", numeric=True),
  dict(q="Variance of the logit for x = 12, n = 80:", opts=["0.098","0.0016","0.15","0.0031"], ans=0, why="1/12+1/68.", numeric=True),
  dict(q="Why not pool raw proportions near 0?", opts=["Non-normal; variance depends on p","Software","Always wrong","Cost"], ans=0, why="Skewness."),
  dict(q="Prevalence I² is typically...", opts=["Very high","Zero","Moderate","Undefined"], ans=0, why="Real population differences."),
  dict(q="A GLMM approach...", opts=["Avoids transformations and handles zeros","Needs no software","Is always faster","Gives fixed effect only"], ans=0, why="Binomial model.")])

# ===================================================================== 48
add(id=48, title="Rare-event meta-analysis", last_verified=V, prerequisites=["Modules 28, 32, 35"],
 objectives=["Explain why zero cells and rare events break standard inverse-variance methods.", "Compare continuity corrections, Mantel-Haenszel, Peto, GLMM and Bayesian approaches.", "Perform and report a continuity-correction sensitivity analysis."],
 why="Adverse events and rare outcomes produce 2×2 tables with zero cells; the choice of method changes the answer, and ignoring this is a major source of unreliable conclusions.",
 plain="""With events in a few participants, the log odds ratio is undefined when any cell is zero. A **continuity correction** adds a small number (0.5 conventionally) to the cells - a pragmatic patch that biases estimates toward the null and affects the weights; its value is arbitrary. **Mantel-Haenszel** (MH) methods pool counts without requiring non-zero cells and perform well for rare events when arms are balanced and there are no large treatment effects; **Peto** OR is accurate for very rare events with balanced arms and moderate effects but biased otherwise. **Studies with zero events in both arms** are uninformative on the relative scale but may inform absolute risks; excluding them is not free of assumptions. **Exact/GLMM and Bayesian** binomial models use the data without corrections but require more expertise (Bradburn et al. 2007; Sweeting et al. 2004; Efthimiou 2018).""",
 intermediate="""**Sensitivity analysis is mandatory:** repeat the analysis with different corrections (0.01, 0.1, 0.5, 1) and with MH/Peto and GLMM; if conclusions change, the data do not support a firm conclusion. **Choose relative vs absolute scale** consciously; risk differences with zeros behave differently. Use the **treatment-arm continuity correction** (proportional to the reciprocal of opposite arm size) in some software to reduce bias. Report the number of studies with zero events in one or both arms and how they were handled. **MetaLab implements** MH, Peto and the continuity-correction sensitivity; GLMM/beta-binomial/Bayesian rare-event models are external workflows.""",
 advanced="""Under extreme sparsity none of the standard approaches are reliably unbiased; exact methods and Bayesian models with a prior on baseline risk are sometimes preferred. Beware of 'double-zero' studies: dropping them can bias absolute-risk estimates. Heterogeneity estimates (τ²) are unreliable with sparse data. Pre-specify handling of zeros in the protocol.""",
 assumptions=["Counts are binomial/Poisson distributed.", "MH/Peto: common effect or modest heterogeneity.", "Continuity correction magnitude does not drive conclusions (to be checked)."],
 formulas=[dict(name="Continuity correction for a zero cell", tex=r"\widehat{OR}_{cc}=\frac{(a+c)(d+c)}{(b+c)(c'+c)}\ \ (\text{0.5 added to each cell of a table with a zero cell})", symbols={"a,b,c,d":"2x2 cells","c":"correction constant"})],
 worked_example="""Niel-Weise (2007) trials (18 studies, many with zero cells; metadat `dat.nielweise2007`; log OR pooled by REML after adding the correction to tables with a zero cell, metafor reference): corrections 0.01, 0.1, 0.5, 1 give pooled ln OR = **−0.837, −0.898, −0.960, −0.940** (OR 0.43, 0.41, 0.38, 0.39) with τ² = 0, 0.0022, 0.0139, 0. The estimate moves by about 0.12 log units (OR 0.43 to 0.38) purely through the arbitrary correction. The direction and rough size are stable here, but the heterogeneity estimate is not - a typical pattern.""",
 examples=[("Preclinical","Rare adverse events in animal studies."),("Clinical","Serious adverse events."),("Ecology","Rare species detections."),("Genetics","Rare variant carriers."),("Public health","Vaccine safety signals.")],
 mistakes=["Adding 0.5 without a sensitivity analysis.","Dropping all zero-event studies silently.","Using Peto with very unbalanced arms.","Interpreting τ² from sparse data."],
 misconceptions=[("'Zero events means no risk.'","It means no events observed."),("'A continuity correction is neutral.'","It biases toward the null.")],
 controversies=["Best method for rare events.", "Handling double-zero studies."],
 decision_tree=[("Zero cells present?","Run MH/Peto and corrections in sensitivity."),("Very sparse and unbalanced?","GLMM/Bayesian/external."),("Double zeros?","Report and test exclusion assumptions.")],
 exercises=["Re-pool a table with 3 zero-cell studies using corrections 0.1, 0.5, 1.", "Compare MH and Peto OR for BCG-like data in the Statistics Lab.", "Write the protocol sentence for zero handling."],
 integrity="Pre-specify zero handling and report all sensitivity analyses; do not choose the correction that gives the preferred result.", further=["bradburn2007","sweeting2004","efthimiou2018"],
 coding=dict(r='library(metafor)\nd <- dat.nielweise2007\nfor (a in c(0.01, 0.1, 0.5, 1)) { e <- escalc("OR", ai = ai, n1i = n1i, ci = ci, n2i = n2i, data = d, add = a, to = "only0"); e <- e[!is.na(e$yi), ]; cat(a, round(rma(yi, vi, data = e, method = "REML")$beta, 4), "\\n") }', python='from metalab import advanced2 as B\nfrom metalab.datasets import BCG\na,b,c,d = zip(*BCG); r = B.cc_sensitivity(a,b,c,d,"OR"); print({k:round(v["est"],4) for k,v in r.items()})'),
 application="**Milestone 8/9:** if adverse events are rare, specify in the SAP: primary method for zeros, sensitivity methods and how double-zero studies are treated.", checklist=["Zero handling pre-specified","Sensitivity to corrections","MH/Peto compared","Double zeros reported"],
 quiz=[dict(q="Pooled ln OR with correction 0.5 (Niel-Weise reference):", opts=["−0.960","−0.837","0.5","0"], ans=0, why="Reference value.", numeric=True),
  dict(q="Why can a continuity correction bias results?", opts=["It adds data that were not observed, pulling estimates toward the null","It improves power","It removes heterogeneity","It is exact"], ans=0, why="Arbitrary added counts."),
  dict(q="Peto OR is unreliable when...", opts=["Arms are very unbalanced or effects are large","There are zeros","k is large","n is large"], ans=0, why="Approximation properties."),
  dict(q="A study with zero events in both arms...", opts=["Is uninformative for relative effects but may inform absolute risk","Proves safety","Must be discarded silently","Doubles the weight"], ans=0, why="No contrast information."),
  dict(q="Sensitivity analysis means...", opts=["Re-running with alternative methods/corrections and comparing","Removing outliers","Increasing n","Changing the question"], ans=0, why="Robustness check.")])

