add(id=49, title="Additional specialised quantitative methods", last_verified=V, prerequisites=["Modules 33, 34, 35, 36"],
 objectives=["Understand trim-and-fill, PET-PEESE and selection models as sensitivity analyses for small-study effects.", "Plan power and number of studies realistically, including heterogeneity.", "Know the scope and limitations of meta-analysis of variances, trial sequential analysis and similar extras."],
 why="Beyond the standard model there are methods that every reviewer meets in papers and referee reports. Knowing what they do, what they assume and when they mislead protects against both overuse and blind reliance.",
 plain="""**Trim-and-fill** (Duval & Tweedie) removes the most extreme studies from the asymmetric side of the funnel plot until symmetric, re-estimates the centre, and imputes mirror-image 'missing' studies. It is a **sensitivity analysis**, not a correction: asymmetry can come from heterogeneity, chance or true small-study differences. **PET/PEESE** regress effect on SE (or variance) and use the intercept as the effect for a hypothetical infinitely precise study; both are biased in many realistic settings (heterogeneity, few studies, effects near zero). **Selection models** model the probability of publication by p-value and can be informative but require many studies and assumptions. **Power:** the power of a meta-analysis depends on the number of studies, their sizes and especially heterogeneity; with τ² > 0 adding participants to existing studies does not help much but adding studies does.""",
 intermediate="""**Benchmarks in MetaLab (metafor 4.4.0):** trim-and-fill L0/R0 (identical k0, side and imputed data on five datasets); PET/PEESE equal base R `lm` with weights 1/v; power from closed-form formulas with a Monte-Carlo check. **Interpretation:** report unadjusted and adjusted estimates side by side; never present the adjusted estimate as the 'true' effect (the tool warns). With < 10 studies, asymmetry tests and adjustments have little power (Sterne et al. 2011). **Other extras:** **meta-analysis of variances** (lnVR, lnCVR; Nakagawa et al.) addresses questions about variability; **trial sequential analysis** controls repeated testing in cumulative meta-analysis and needs a specified information size (not implemented); **meta-analysis of SDs** requires care because SD and mean are correlated.""",
 advanced="""Selection models (e.g. step models with cut-points at p = 0.025) are sensitive to the number and distribution of studies and to heterogeneity; the R workflow is in `validation/external_workflows/05_selection_models.R` (not run in the build environment). **Realistic power:** power for a random-effects meta-analysis with Hartung-Knapp inference is lower than the normal-approximation formula; use simulation. Post-hoc power is uninformative. **Dependence** among effects invalidates funnel-plot methods unless handled (Modules 39-40).""",
 assumptions=["Trim-and-fill: asymmetry is caused by suppression of extreme results.", "PET/PEESE: a linear relation between effect and SE (or variance) mirrors bias.", "Power formulas: τ² known, equal sizes, normal approximation."],
 formulas=[dict(name="Power of the z-test for the pooled mean (known τ², equal variances)", tex=r"1-\Phi\big(z_{1-\alpha/2}-\lambda\big)+\Phi\big(-z_{1-\alpha/2}-\lambda\big),\quad \lambda=\frac{|\theta|}{\sqrt{(v+\tau^2)/k}}", symbols={"\\theta":"true mean effect","v":"typical sampling variance","k":"number of studies"})],
 worked_example="""Benchmarked on five datasets (metafor `trimfill`, REML): BCG log RR - L0 imputes **1** study (R0: 0); Raudenbush - **3** (R0: 2); Bangert-Drowns - **7** (R0: 0); Hackshaw - **7** (R0: 7); Normand - **0** (R0: 1). The estimators disagree, which is itself information: the 'number of missing studies' is not a robust quantity. **Power:** θ = 0.3, per-study SMD variance with n = 30 per arm = 0.0674, k = 10, τ² = 0.02: power = **0.894** (k = 20: 0.995); with τ² = 0 power is 0.955 at k = 10, and with τ² = 0.1 it is only 0.640; the number of studies needed for 80% power is **6 (τ² = 0), 8 (τ² = 0.02) and 15 (τ² = 0.1)**. (MetaLab's formula assumes τ² is known; true power with estimated τ² and HKSJ is lower.)""",
 examples=[("Preclinical","Funnel asymmetry in small animal studies."),("Clinical","Small-study effects in trials."),("Ecology","Sensitivity of effects to non-significant results."),("Genetics","Effect inflation in small studies."),("Education","Publication bias in intervention studies.")],
 mistakes=["Reporting the trim-and-fill estimate as the corrected truth.","Using PET-PEESE with 6 studies.","Planning power without heterogeneity.","Running many bias tests and reporting the one that fits."],
 misconceptions=[("'Trim-and-fill detects publication bias.'","It imputes studies under a specific asymmetry assumption."),("'A non-significant Egger test means no bias.'","Low power.")],
 controversies=["Conditional PET-PEESE.", "Selection models vs trim-and-fill.", "Value of power calculations for meta-analyses."],
 decision_tree=[("k ≥ 10 and asymmetry concern?","Funnel + Egger + trim-and-fill/PET-PEESE as sensitivity (report all)."),("k < 10?","No formal adjustments; narrative caution."),("Planning a meta-analysis?","Power by simulation with plausible τ².")],
 exercises=["Run trim-and-fill (L0, R0) on the BCG data and compare adjusted vs unadjusted.", "Compute power for k = 5, 10, 20 with τ² = 0, 0.02, 0.1 at θ = 0.3, v = 0.0674.", "Explain why power does not improve much with larger studies if τ² > 0."],
 integrity="Report unadjusted and adjusted estimates; state that adjusted estimates are sensitivity analyses.", further=["sterne2011funnel","page2020bias","sterne2001","egger1997"],
 coding=dict(r='library(metafor)\nd <- escalc("RR", ai = tpos, bi = tneg, ci = cpos, di = cneg, data = dat.bcg)\nres <- rma(yi, vi, data = d, method = "REML")\nc(L0 = trimfill(res, estimator = "L0")$k0, R0 = trimfill(res, estimator = "R0")$k0)   # 1 0', python='from metalab import advanced2 as B, stats as S\nfrom metalab.datasets import BCG\nys, vs = zip(*[S.log_risk_ratio(a, a+b, c, c+d, cc=0.5) for a,b,c,d in BCG])\nr = B.trim_fill(ys, vs, "L0"); print(r["k0"], r["est"], r["est_unadjusted"])'),
 application="**Milestone 9:** specify publication-bias analyses in the SAP (funnel, Egger, trim-and-fill, PET-PEESE as sensitivity) and the minimum k.", checklist=["Bias methods pre-specified","k ≥ 10 for tests","Unadjusted and adjusted shown","Power planned with τ²"],
 quiz=[dict(q="Trim-and-fill L0 on BCG imputes how many studies (metafor benchmark)?", opts=["1","0","3","7"], ans=0, why="k0 = 1.", numeric=True),
  dict(q="Trim-and-fill is best described as...", opts=["A sensitivity analysis under a specific asymmetry assumption","A correction to the true effect","A test of bias","An estimate of heterogeneity"], ans=0, why="Assumption-dependent."),
  dict(q="With τ² > 0, power mostly improves by...", opts=["Adding studies","Adding participants to existing studies","Lowering α","Using fixed effect"], ans=0, why="τ² limits gain from larger studies."),
  dict(q="PET-PEESE intercepts are...", opts=["Extrapolations to zero SE/variance that can be biased","Exact corrections","Tests of heterogeneity","Sample sizes"], ans=0, why="Model-based extrapolation."),
  dict(q="Post-hoc power from the observed effect is...", opts=["Uninformative beyond the p-value","Required","Best practice","Equal to 80%"], ans=0, why="One-to-one with p.")])
